window.WBSC_QDICT = window.WBSC_QDICT || {};
WBSC_QDICT["es"] = {"m01-mkc":{"questions":[{"options":["Situar los ojos justo por dentro del borde interior del plato, en lugar de usar la oreja interior como referencia de alineación.","Usar una Buena Alineación Pélvica (GPA), con el ombligo apuntando entre el centro de la parte delantera del plato y no más allá de la esquina delantera exterior.","Usar una postura equilibrada con los pies separados aproximadamente al ancho de los hombros o más, ajustando la anchura para que el árbitro vea la zona de strike desde el esternón y la rodilla del bateador y los bordes interior y exterior.","Todas las anteriores."],"q":"¿Qué afirmaciones describen la colocación en el plato que enseña la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"La guía cambia la referencia de alineación en el slot, de la oreja interior a los ojos justo por dentro del borde del plato, enseña de forma explícita la GPA y revisa la recomendación sobre la anchura de la postura. La alineación pélvica ya se describía en el manual anterior; la denominación GPA y la instrucción más completa son novedades."},{"options":["Moverte en diagonal hacia la base para mantener la misma distancia de trabajo cercana.","Moverte en ángulo recto o más respecto a la línea de base para crear distancia de trabajo y abrir el ángulo de visión según sea necesario, manteniendo a la vista los cuatro elementos esenciales.","Quedarte en la posición inicial, porque una jugada forzada debe juzgarse desde la misma distancia que una jugada de tag.","Acercarte hasta que la base ocupe todo tu campo visual."],"q":"Estás trabajando desde una posición inicial cercana con corredor en base cuando se desarrolla una jugada forzada. ¿Qué primer movimiento sigue mejor la nueva indicación de la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"La nueva instrucción se centra en la trayectoria del movimiento. Un primer movimiento en ángulo recto o más respecto a la línea de base crea distancia y mejora la separación visual. Moverse en diagonal hacia la base mantiene en gran medida la distancia corta propia de una jugada de tag."},{"options":["Pedir ayuda antes de decidir y transferir automáticamente la decisión al árbitro de home.","Cantar out al corredor porque la pelota llegó al fildeador antes de que el corredor llegara a la base.","Moverte de forma dinámica para mantener a la vista los cuatro elementos esenciales siempre que sea posible. Tomar una decisión sobre la jugada y luego consultar a todo el equipo arbitral si hace falta ayuda; no pasar la decisión a otro árbitro salvo que estés seguro de que tiene toda la información necesaria para decidir la jugada completa.","Dejar la jugada sin decidir hasta que un entrenador pida una reunión."],"q":"Un tiro desviado lleva al primera base hacia home para un posible tag de barrido. Eres el árbitro de base responsable, pero tienes bloqueada la visión del tag. ¿Qué procedimiento sigue la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"El árbitro responsable debe tomar una decisión y después consultar al equipo arbitral si es necesario. Un compañero puede haber visto el tag pero haberse perdido otra parte de la jugada, así que la decisión no debe transferirse sin más. Nunca adivines un out."},{"options":["Cantar con claridad \"Strike tres... ¡Out!\" y reforzar el out si el bateador empieza a correr hacia primera.","Hacer solo la señal de strike y dejar que los jugadores determinen si el bateador está out.","Cantar \"No atrapada\" y enviar al bateador a primera base.","Esperar a que la defensa apele antes de declarar out al bateador."],"q":"Un tercer strike cantado no es atrapado. La primera base está ocupada y hay un out. ¿Qué comunicación sigue la indicación explícita sobre el tercer strike de la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"Con la primera base ocupada y menos de dos outs, el bateador queda out automáticamente en el tercer strike aunque no sea atrapado. La guía exige expresamente comunicar con claridad el strike y el out, incluido reforzarlo si el bateador empieza a correr hacia primera."},{"options":["Retrasar toda comunicación verbal hasta después de comprobar al corredor que anota.","Decir \"Tag\" en voz alta en el momento exacto del tag para ayudar al árbitro de home a juzgar el momento, y completar la decisión después de juzgar el control de la pelota. El árbitro de home señalará home y hará la señal con un dedo si juzga que la carrera anotó, o cruzará los brazos sobre los hombros si la carrera no anota.","Cantar \"Out\" en cuanto el guante toque al corredor, antes de juzgar la posesión.","Anunciar desde la base donde se produce el tag si la carrera cuenta."],"q":"Hay dos outs. Un corredor se acerca a home mientras otro corredor afronta una jugada de tag en otra base. ¿Qué comunicación verbal adicional recomienda preferentemente la Guía de Aprendizaje de Fundamentos de enero de 2026 al árbitro de base?","why":"La guía recomienda una señal verbal inmediata y fuerte, \"Tag\", en el punto de contacto. Esto ayuda al árbitro de home a comparar el tag con el toque de home mientras el árbitro que decide juzga el control de la pelota. La señal no declara por sí sola un out; si el corredor es safe, usa la señal y la voz de safe según corresponda."}],"title":"Guía de Aprendizaje de Fundamentos","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m01-pca":{"questions":[{"options":["Situar los ojos justo por dentro del borde interior del plato, en lugar de usar la oreja interior como referencia de alineación.","Usar una Buena Alineación Pélvica (GPA), con el ombligo apuntando entre el centro de la parte delantera del plato y no más allá de la esquina delantera exterior.","Usar una postura equilibrada con los pies separados aproximadamente al ancho de los hombros o más, ajustando la anchura para que el árbitro vea la zona de strike desde el esternón y la rodilla del bateador y los bordes interior y exterior.","Todas las anteriores."],"q":"¿Qué afirmaciones describen la colocación en el plato que enseña la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"La guía cambia la referencia de alineación en el slot, de la oreja interior a los ojos justo por dentro del borde del plato, enseña de forma explícita la GPA y revisa la recomendación sobre la anchura de la postura. La alineación pélvica ya se describía en el manual anterior; la denominación GPA y la instrucción más completa son novedades."},{"options":["Moverte en diagonal hacia la base para mantener la misma distancia de trabajo cercana.","Moverte en ángulo recto o más respecto a la línea de base para crear distancia de trabajo y abrir el ángulo de visión según sea necesario, manteniendo a la vista los cuatro elementos esenciales.","Quedarte en la posición inicial, porque una jugada forzada debe juzgarse desde la misma distancia que una jugada de tag.","Acercarte hasta que la base ocupe todo tu campo visual."],"q":"Estás trabajando desde una posición inicial cercana con corredor en base cuando se desarrolla una jugada forzada. ¿Qué primer movimiento sigue mejor la nueva indicación de la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"La nueva instrucción se centra en la trayectoria del movimiento. Un primer movimiento en ángulo recto o más respecto a la línea de base crea distancia y mejora la separación visual. Moverse en diagonal hacia la base mantiene en gran medida la distancia corta propia de una jugada de tag."},{"options":["Pedir ayuda antes de decidir y transferir automáticamente la decisión al árbitro de home.","Cantar out al corredor porque la pelota llegó al fildeador antes de que el corredor llegara a la base.","Moverte de forma dinámica para mantener a la vista los cuatro elementos esenciales siempre que sea posible. Tomar una decisión sobre la jugada y luego consultar a todo el equipo arbitral si hace falta ayuda; no pasar la decisión a otro árbitro salvo que estés seguro de que tiene toda la información necesaria para decidir la jugada completa.","Dejar la jugada sin decidir hasta que un entrenador pida una reunión."],"q":"Un tiro desviado lleva al primera base hacia home para un posible tag de barrido. Eres el árbitro de base responsable, pero tienes bloqueada la visión del tag. ¿Qué procedimiento sigue la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"El árbitro responsable debe tomar una decisión y después consultar al equipo arbitral si es necesario. Un compañero puede haber visto el tag pero haberse perdido otra parte de la jugada, así que la decisión no debe transferirse sin más. Nunca adivines un out."},{"options":["Cantar con claridad \"Strike tres... ¡Out!\" y reforzar el out si el bateador empieza a correr hacia primera.","Hacer solo la señal de strike y dejar que los jugadores determinen si el bateador está out.","Cantar \"No atrapada\" y enviar al bateador a primera base.","Esperar a que la defensa apele antes de declarar out al bateador."],"q":"Un tercer strike cantado no es atrapado. La primera base está ocupada y hay un out. ¿Qué comunicación sigue la indicación explícita sobre el tercer strike de la Guía de Aprendizaje de Fundamentos de enero de 2026?","why":"Con la primera base ocupada y menos de dos outs, el bateador queda out automáticamente en el tercer strike aunque no sea atrapado. La guía exige expresamente comunicar con claridad el strike y el out, incluido reforzarlo si el bateador empieza a correr hacia primera."},{"options":["Retrasar toda comunicación verbal hasta después de comprobar al corredor que anota.","Decir \"Tag\" en voz alta en el momento exacto del tag para ayudar al árbitro de home a juzgar el momento, y completar la decisión después de juzgar el control de la pelota. El árbitro de home señalará home y hará la señal con un dedo si juzga que la carrera anotó, o cruzará los brazos sobre los hombros si la carrera no anota.","Cantar \"Out\" en cuanto el guante toque al corredor, antes de juzgar la posesión.","Anunciar desde la base donde se produce el tag si la carrera cuenta."],"q":"Hay dos outs. Un corredor se acerca a home mientras otro corredor afronta una jugada de tag en otra base. ¿Qué comunicación verbal adicional recomienda preferentemente la Guía de Aprendizaje de Fundamentos de enero de 2026 al árbitro de base?","why":"La guía recomienda una señal verbal inmediata y fuerte, \"Tag\", en el punto de contacto. Esto ayuda al árbitro de home a comparar el tag con el toque de home mientras el árbitro que decide juzga el control de la pelota. La señal no declara por sí sola un out; si el corredor es safe, usa la señal y la voz de safe según corresponda."},{"options":["Acercarte hasta que la base quede directamente bajo tus ojos.","Trabajar justo antes del borde de entrada, con un ligero ángulo y la profundidad suficiente para mantener visualmente separados los Cuatro Elementos Esenciales.","Colocarte directamente en la línea del tiro y quedarte ahí.","Mantener la misma posición y juzgar la jugada sobre todo por el sonido de la atrapada."],"q":"Un corredor avanza de primera a segunda en una jugada de tag. Tu visión está casi directamente sobre la segunda base, de modo que la pelota, el fildeador, el corredor y la base parecen alineados. ¿Qué ajuste sigue la guía?","why":"Trabajar justo antes del borde de entrada, con un ángulo y una profundidad adecuados, mantiene los elementos separados visualmente y te ayuda a juzgar el momento del tag y el toque de la base."},{"options":["Tratar la posición de observación como un punto fijo y decidir desde ahí.","Ir a la zona de espera y decidir desde ahí.","Quedarte en el punto inicial y suponer que el tag se aplicó.","Usar la posición de observación para leer la jugada en desarrollo y luego ajustarte a una posición de decisión con visión sin obstáculos antes de señalar."],"q":"En una jugada de tag que se está desarrollando, alcanzas una buena posición de observación, pero el fildeador se cruza en tu línea de visión. ¿Cómo debes usar las posiciones de observación y de decisión que describe la guía?","why":"La posición de observación es una zona desde la que leer la jugada, no necesariamente la posición final de decisión. Ajústate a medida que se desarrolla la jugada para ver la acción completa antes de señalar."},{"options":["Usar los 90 grados como referencia y ajustarte después para obtener una visión sin obstáculos de los Cuatro Elementos Esenciales.","Mantener el ángulo exacto de 90 grados aunque el tag quede oculto.","Colocarte directamente sobre la base para no necesitar ningún ángulo.","Mantener el ángulo y cantar out al corredor si el tiro llega primero."],"q":"En una jugada de tag, la posición nominal a 90 grados deja al fildeador entre tú y el tag. ¿Qué enfoque sigue el tratamiento del ángulo de 90 grados en la guía?","why":"El ángulo de 90 grados es una pauta, no un requisito absoluto. Ver la jugada con claridad tiene prioridad sobre alcanzar un ángulo exacto. El manual anterior ya exigía ajustar el ángulo; la guía de 2026 hace explícito este concepto de referencia."},{"options":["Mirar solo el pie del corredor y deducir el tag por la reacción del fildeador.","Quedarte quieto aunque el fildeador tape el guante.","Seguir la pelota o el conjunto pelota-guante hasta el tag, ajustándote al ritmo de la jugada en desarrollo, manteniendo la cabeza lo más quieta posible y los demás elementos a la vista.","Mirar solo el guante e ignorar la posición del corredor respecto a la base."],"q":"Cuando un corredor se desliza apartándose de un tag y el fildeador se estira para alcanzarlo, ¿qué foco y qué movimiento siguen mejor la instrucción de la guía sobre las jugadas de tag?","why":"La guía vincula explícitamente el movimiento al conjunto pelota-guante y a la aplicación del tag. Mantén a la vista los Cuatro Elementos Esenciales, ajústate cuando sea necesario y mantén el foco de la cabeza y la vista en todo momento."},{"options":["Salir en cada pelota bateada al outfield, sea cual sea la posibilidad de atrapada.","Usar la valoración previa al lanzamiento y la comunicación del equipo arbitral para no salir sin necesidad y conservar una cobertura eficaz de las bases, teniendo en cuenta que en cualquier fly que pueda ser atrapado, atrapado a ras de suelo o cerca de la línea de fair/foul o del poste, los árbitros deben salir.","Cantar \"No atrapada\" de inmediato, antes de que la pelota caiga.","Salir primero y volver luego por la zona de otro árbitro mientras se desarrolla una jugada en base."],"q":"Durante la preparación previa al lanzamiento, valoras la profundidad y la capacidad de los jardineros. Después se batea un fly a tu zona de cobertura sin posibilidades reales de ser atrapado. ¿Qué destaca la nueva indicación sobre la cobertura del outfield?","why":"La sección 9.2.1 advierte específicamente contra salir en pelotas sin posibilidades reales de ser atrapadas. Lee la jugada, ten en cuenta la cobertura asignada y comunícate para que el equipo arbitral mantenga una cobertura eficaz del outfield y de las bases."},{"options":["Esperar a una atrapada completa antes de indicar fair o foul.","Declararla foul porque se soltó en territorio foul.","Usar la posición de los pies del fildeador en el momento en que suelta la pelota para determinar fair o foul.","Seguir la pelota, observar su posición en el primer toque e indicar fair en ese momento; que se suelte después en territorio foul no cambia ese estado."],"q":"Un fly cerca de la línea de foul es tocado primero por un jardinero mientras la pelota está sobre territorio fair. El fildeador hace malabares con ella, pasa a territorio foul y la suelta. ¿Qué momento y qué estado se derivan de la instrucción de la guía sobre el primer toque?","why":"La nueva sección separa el momento del fair/foul del momento de la atrapada. En este fly, el estado fair/foul lo determina la posición de la pelota en el primer toque, y la indicación no debe esperar a una atrapada completa."},{"options":["Dar el safe con el énfasis rutinario adecuado; reservar el señalamiento descriptivo y el \"Off\" enérgico para una jugada que necesite ese énfasis y esa explicación.","Señalar siempre con energía y cantar \"Off\" en voz alta, por obvia que sea la jugada.","Cantar out al corredor porque la pelota llegó antes que él.","No tomar ninguna decisión porque el pie levantado era evidente."],"q":"En primera base, el fildeador está claramente fuera de la base mucho antes de que llegue el tiro. El corredor llega a primera sin ser tocado. ¿Cómo debes aplicar el nuevo énfasis de la guía en las decisiones de pie levantado?","why":"La guía de 2026 indica que no hay que vender innecesariamente un pie levantado evidente. La mecánica descriptiva más enérgica es para un pie levantado tardío o ajustado en el que la razón del safe debe quedar clara. Reserva este tipo de mecánica para cuando tenga más impacto, solo cuando haga falta."},{"options":["Esperar a que el árbitro de home termine antes de dirigirse a los jugadores.","Permitir jugadores de más cerca del plato porque la pelota está muerta.","Controlar la zona del bateador en espera y mantener segura la zona del plato; normalmente se encarga el árbitro de base más cercano al dugout ofensivo y los compañeros se ajustan según sea necesario.","Reanudar el juego para que los jugadores de más vuelvan al dugout."],"q":"Durante una entrada, el árbitro de home está ocupado con sustituciones. La pelota está muerta y varios jugadores ofensivos de más se reúnen cerca de home con el bateador en espera. ¿Qué deben hacer los árbitros de base?","why":"La nueva sección sobre pelota muerta da a los árbitros de base responsabilidades concretas mientras el árbitro de home gestiona las notificaciones. Arbitra de forma preventiva, controla a los jugadores no autorizados y mantén una zona de trabajo segura alrededor de home."},{"options":["Diez minutos después, porque el periodo original de 30 minutos casi se ha cumplido.","No antes de 30 minutos después de ese trueno, siempre que no haya más rayos ni truenos y la reanudación se apruebe según los procedimientos de la competición.","De inmediato, porque un trueno sin rayo visible no afecta a la reanudación.","En cuanto los dos entrenadores principales acepten reanudar."],"q":"El juego se ha suspendido por rayos. Veinte minutos después del último rayo visto, se vuelve a oír un trueno. Según la guía, ¿cuándo puede reanudarse el juego?","why":"El protocolo de 2026 cuenta el tiempo de espera desde el último rayo visto o el último trueno oído. Un trueno posterior inicia una nueva espera de 30 minutos. Consulta al UIC o a los responsables del torneo y aplica los procedimientos de la competición."},{"options":["Plantearlo públicamente ante los equipos para que todos oigan la explicación.","Decirle al compañero qué hizo mal antes de dejarle describir la jugada.","Evitar hablar de decisiones difíciles, porque una reunión posterior solo debe tratar las jugadas bien resueltas.","Dejar que el compañero comparta sus observaciones, pedir permiso antes de cuestionar su decisión y comentar la jugada con honestidad, respeto y confidencialidad, centrándose en aprender."],"q":"En el vestuario, después del partido, quieres cuestionar la decisión de un compañero en una jugada difícil. ¿Qué enfoque sigue la indicación de la guía sobre la reunión posterior del equipo arbitral?","why":"La indicación ampliada sobre la reunión posterior pide dejar que los compañeros compartan sus observaciones y pedir permiso antes de cuestionarlos. Mantén la conversación confidencial y constructiva, y escucha todos los puntos de vista."},{"options":["Un jugador retirado por una infracción de las reglas puede quedarse en el dugout y puede dirigir; una persona expulsada debe abandonar el partido e ir al vestuario o abandonar por completo la instalación.","Tanto el jugador retirado como la persona expulsada deben quedarse en el dugout.","Un jugador retirado puede seguir jugando si el entrenador está de acuerdo.","La expulsión se aplica solo a los entrenadores y la retirada solo a los jugadores."],"q":"Un jugador es retirado por una infracción de las reglas en lugar de ser expulsado por mala conducta. ¿Qué distinción exige la Guía de Aprendizaje de Fundamentos que reconozca el equipo arbitral?","why":"La guía distingue la expulsión de la retirada. Su instrucción es que la persona expulsada abandona la instalación; un jugador retirado por una infracción de las reglas puede quedarse en el dugout y dirigir. Esto no hace que el jugador retirado pueda seguir jugando."},{"options":["Anunciar primero la nueva decisión al público y dejar que los entrenadores pidan los detalles.","Pedir a los dos entrenadores que se unan a la conversación del equipo arbitral antes de decidir.","Informar primero al equipo afectado, dar una explicación sencilla y comunicar después con claridad la decisión final.","Cambiar la señal sin explicarla para que el juego se reanude antes."],"q":"Un compañero te aporta información adicional fiable y, tras consultarlo con el equipo arbitral, decides cambiar tu decisión. ¿Qué secuencia de comunicación indica la guía?","why":"La consulta del equipo arbitral se hace lejos de jugadores y entrenadores. Si la decisión cambia, informa primero al equipo afectado, explícalo de forma sencilla y comunica con claridad la decisión final. La consulta debe basarse en información, no solo en la presión."},{"options":["Decir al anotador que el equipo sigue teniendo diez jugadores porque el DP continúa en el orden al bate.","Cuando el DP defiende en lugar del FLEX, se trata como una sustitución del FLEX o de su sustituto y debe comunicarse al árbitro. Confirmar con el entrenador y el anotador que el equipo juega ahora con nueve, además de registrar y comunicar el cambio.","Permitir que el entrenador comunique el cambio directamente al anotador sin pasar por el árbitro de home.","Esperar al final de la entrada para registrar si el FLEX salió del partido."],"q":"El DP ocupa la posición defensiva del jugador FLEX y el FLEX sale del partido. ¿Qué confirmación concreta añade la guía al proceso de gestión de la alineación?","why":"En un cambio en el que el DP o el FLEX salen o vuelven al partido, la guía indica explícitamente al árbitro que confirme con el entrenador y el anotador si el equipo juega con nueve o con diez. Aquí el FLEX ha salido, así que el equipo tiene nueve."},{"options":["Permanecer fijo en la posición de set durante todo el turno al bate.","Cambiar el ritmo de tu decisión en el siguiente lanzamiento para obligarte a concentrarte.","Repasar mentalmente el lanzamiento anterior mientras se realiza el siguiente.","Tras completar la decisión y comprobar que no hay acción en curso, dar un paso atrás, relajarte, respirar y fijarte brevemente en el entorno, y volver a concentrarte antes del siguiente lanzamiento."],"q":"Después de varios lanzamientos exigentes, notas que tu concentración disminuye. ¿Qué rutina entre lanzamientos recomienda la guía para mantener el foco?","why":"La guía añade un ciclo deliberado de concentración en cada lanzamiento y una breve pausa entre lanzamientos. La pausa llega tras completar el lanzamiento y la decisión, y no debe distraer de las jugadas en curso del receptor o de los corredores."},{"options":["Aplicar la norma de la WBSC de forma coherente e imparcial, abordando las infracciones claras que afectan a la equidad sin buscar tecnicismos marginales o triviales.","Aplicar la norma nacional del equipo que esté bateando.","Relajar la aplicación de las reglas con los equipos que no conocen la competición internacional.","Cambiar la norma al final del partido para no influir en un resultado ajustado."],"q":"En un torneo, un entrenador dice que hay que ignorar una infracción clara porque en la competición nacional de su equipo se tolera habitualmente. ¿Qué enfoque sigue el marco de la WBSC de la guía?","why":"El nuevo marco establece que el juego de campeonato no varía según las costumbres nacionales de aplicación de las reglas. Aplica una norma WBSC coherente desde el primer lanzamiento hasta el último out, equilibrando una aplicación clara con evitar arbitrar en exceso tecnicismos triviales."}],"title":"Guía de Aprendizaje de Fundamentos","nextLabel":"Continúa con el Módulo 02 - Mecánica de campo de un árbitro"},"m02-mkc":{"questions":[{"options":["La pelota, los jugadores a la defensiva, los jugadores a la ofensiva y la base o la zona de la jugada","La pelota, los corredores, los entrenadores y el marcador","El lanzador, el receptor, el bateador y el infield","La pelota, los fildeadores, las líneas de foul y los dugouts"],"q":"Según la descripción general del Sistema de Un Árbitro, ¿cuáles son los «Cuatro Elementos Esenciales» que el árbitro debe intentar mantener siempre a la vista?"},{"options":["Permanecer detrás del plato hasta que se fildee la pelota","Salir rápidamente de detrás del plato hacia el infield para tener la mejor visión de la jugada","Pedir «Time» de inmediato para reordenar la defensa","Moverse directamente a primera base sin importar adónde se batee la pelota"],"q":"En el Sistema de Un Árbitro, ¿qué debe hacer el árbitro en cada bola bateada, antes de dictaminar nada?"},{"options":["«Umpire-in-Chief» o «UIC»","«Home» o «HU»","«Base Umpire» o «BU»","«Plate» o «PU»"],"q":"Según la sección de Convenciones, ¿cómo se denomina al árbitro de home en todo este manual?"},{"options":["Tres","Siete","Cinco","Diez"],"q":"Según la orientación sobre la posición inicial del árbitro de home, ¿cuántos lanzamientos de calentamiento se permiten a cada lanzador en la primera entrada y con cada lanzador nuevo?"},{"options":["Por el lado derecho, salvo que el bateador sea zurdo","Por el lado más cercano a donde se bateó la pelota","Directamente por el centro, entre el receptor y el bateador","Por el lado izquierdo, incluso con un bateador zurdo"],"q":"En cada bola bateada, ¿por qué lado indica el manual que debe salir el árbitro de home de detrás del receptor?"}],"title":"Fundamentos - Mecánica de campo de un árbitro","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m02-pca":{"questions":[{"options":["Hacia el territorio de foul, en dirección a tercera base","Con decisión, hacia delante del plato en dirección a la zona del lanzador","Directamente por la línea de primera base, siguiendo al bateador-corredor","Quedarse detrás del receptor y dictaminar desde el plato"],"q":"No hay corredores en base y el bateador batea un rodado rutinario al shortstop. Según la mecánica de «Sin corredores en base», ¿hacia dónde debe moverse el árbitro de home para tener la mejor visión de la jugada?"},{"options":["Moverse hacia el territorio de foul, en dirección a tercera base","Moverse hacia delante del plato en dirección a la zona del lanzador, como cuando no hay corredores en base","Permanecer inmóvil detrás del receptor","Correr directamente a primera base"],"q":"Hay un corredor solo en tercera base y el bateador batea un rodado hacia el tercera base. Según la mecánica de «Corredor en tercera base», ¿qué movimiento debe hacer el árbitro de home?"},{"options":["Hacia delante del plato, en dirección a la zona del lanzador","Hacia la línea de foul del jardín derecho","Directamente detrás de segunda base","Hacia el territorio de foul, en dirección a tercera base"],"q":"Con las bases llenas, el bateador batea un fly hacia el jardín derecho corto. De acuerdo con la mecánica de «Bases llenas» (que sigue el mismo patrón que Corredor en tercera base), ¿hacia dónde debe moverse el árbitro?"},{"options":["Dictaminar de inmediato al ver el tiro y luego confirmar con una señal","Señalar primero y después cantar verbalmente","Parar… Esperar… Dictaminar y señalar","Moverse continuamente mientras se dictamina para mantener el ángulo sobre la jugada"],"q":"El árbitro de home se ha movido a la posición para una posible jugada en primera base sobre un rodado. ¿Qué secuencia prescribe el manual para dictaminar?"},{"options":["Solo si la pelota es fair o foul","La distancia de despegue del corredor","Si el fildeador es zurdo o diestro","Si hay atrapada o no"],"q":"Se batea un fly hacia el outfield sin corredores en base. Antes de moverse hacia la base donde se hará la jugada, ¿qué debe juzgar el árbitro?"},{"options":["Puede dictaminar y señalar «Time»","Seguir persiguiendo activamente la jugada por si un corredor intenta avanzar de nuevo","Regresar de inmediato a la zona del dugout","Convocar automáticamente una conferencia con los entrenadores"],"q":"La pelota ha regresado al infield tras una jugada en el outfield y el juego se ha detenido por completo. Según el manual, ¿qué debe hacer el árbitro de home?"},{"options":["El bateador-corredor que va hacia primera base","El corredor de primera base","El corredor de segunda base (el corredor adelantado)","El corredor que esté físicamente más cerca de la posición actual del árbitro"],"q":"Con corredores en primera y segunda base, se batea un fly hacia el jardín izquierdo que puede ser atrapado o no. De acuerdo con la instrucción del Sistema de Un Árbitro de dar prioridad en el posicionamiento, ¿qué corredor debe influir más en la posición del árbitro?"},{"options":["Permanecer fijo en la jugada de primera base hasta que termine por completo","Desplazarse hacia donde puede producirse la siguiente jugada, sobre todo porque es una posible jugada de tag","Pedir «Time» de inmediato en cuanto se suelta el tiro a primera","Moverse al outfield para preparar al siguiente bateador"],"q":"Se batea un rodado con un corredor en primera base. El tiro a primera para el bateador-corredor parece una jugada rutinaria y sin oposición, pero el corredor de primera puede intentar avanzar con el tiro. ¿Qué indica el manual que debe hacer el árbitro?"},{"options":["Mantenerse cerca de la línea para dictaminar fair/foul","Señalar «Out» de inmediato antes de que termine la jugada","Declarar out al corredor por correr fuera de la línea de base","Pedir ayuda al coach de tercera base"],"q":"Se batea con fuerza un rodado por la línea de tercera base con un corredor en tercera. Además de moverse hacia el territorio de foul en dirección a tercera base, ¿qué responsabilidad adicional asigna el manual al árbitro en esta situación?"},{"options":["Colocarse siempre exactamente a mitad de camino entre las dos bases implicadas en la jugada","Asegurarse de que la posición elegida no lo ponga en el camino de un jugador ni de una pelota lanzada","Mirar siempre al lanzador, sin importar dónde se desarrolle la jugada","Mantener siempre una distancia fija respecto a la base"],"q":"Mientras se mueve con decisión para ponerse en posición para una jugada que se está desarrollando, ¿qué principio de posicionamiento debe observar el árbitro, según la descripción general del Sistema de Un Árbitro?"},{"options":["En la placa del lanzador, mirando hacia home","Detrás del receptor en todo momento","A aproximadamente un tercio del camino de home hacia primera base en una media entrada y hacia tercera base en la otra, a unos 30 cm (12 pulgadas) de la línea, en territorio de foul","En segunda base, mirando hacia home"],"q":"En el Sistema de Un Árbitro, ¿dónde se coloca el árbitro de home entre entradas?","why":"El árbitro se coloca mirando al cuadro con las manos relajadas a los lados y la máscara bajo el brazo izquierdo."},{"options":["Siempre del lado de tercera base","Siempre del lado de primera base","Del lado del equipo que sale al campo","Del lado del equipo que sale del campo"],"q":"Entre entradas en el Sistema de Un Árbitro, ¿de qué lado se coloca el árbitro de home?","why":"El árbitro también apura a los equipos para que entren y salgan del campo."},{"options":["Cinco","Dos","Tres","Ocho"],"q":"¿Cuántos lanzamientos de calentamiento se permiten al inicio de cada entrada después de la primera?","why":"Se permiten cinco lanzamientos de calentamiento a cada lanzador en la primera entrada y con cada nuevo lanzador."},{"options":["Cuándo se ha lanzado el penúltimo lanzamiento de calentamiento","Cuándo se ha lanzado el primer lanzamiento de calentamiento","Nada; el receptor cuenta los lanzamientos","Cuál es el último lanzamiento, solo si se lo preguntan"],"q":"Durante los lanzamientos de calentamiento, ¿qué debe decirle el árbitro de home al receptor?","why":"Después de los lanzamientos de calentamiento, el árbitro limpia el plato y se coloca detrás del receptor."},{"options":["Dando un paso recto hacia atrás","Por la derecha, incluso con un bateador derecho","Por el lado del bateador","Por la izquierda, incluso con un bateador zurdo"],"q":"En cada batazo en el Sistema de Un Árbitro, ¿por dónde sale el árbitro de home de detrás del receptor?","why":"Si la pelota va cerca de la línea de foul, el árbitro se mueve a la línea y se coloca a horcajadas sobre ella para decidir si es fair o foul."},{"options":["Solo al corredor de tercera base","Al corredor de adelante","Al jugador de campo que tiene la pelota","Al bateador-corredor"],"q":"Con corredores en base, ¿a quién dice el Sistema de Un Árbitro que se debe dar prioridad en el posicionamiento del árbitro?","why":"En cada batazo el árbitro sale de detrás del plato hacia el cuadro para tener la mejor vista de la jugada que se desarrolla."},{"options":["Esperar a que el entrenador pregunte","Nunca se debe cantar una jugada sin salir de detrás del plato","Cantar las jugadas desde detrás del plato para no estorbar","Cantar la jugada antes de que llegue la pelota"],"q":"¿Qué dice el manual del Sistema de Un Árbitro sobre cantar una jugada?","why":"El árbitro único no tiene compañero que le ayude, así que debe moverse con determinación para obtener la mejor posición posible, detenerse y cantar la jugada."},{"options":["Para hacer señales a los entrenadores","Para contar el número de tiros","Para saber qué base limpiar","Por si la pelota sale del campo de juego"],"q":"¿Por qué debe saber el árbitro del Sistema de Un Árbitro dónde están los corredores cada vez que se lanza la pelota?","why":"El árbitro también debe echar un vistazo rápido a los corredores cuando tocan las bases, sobre todo al anotar en home."},{"options":["En la cabeza","Bajo el brazo derecho","Bajo el brazo izquierdo","En la bolsa de pelotas"],"q":"¿Dónde lleva la máscara el árbitro de home entre entradas en el Sistema de Un Árbitro?","why":"Durante la primera media entrada y cuando hay un cambio de lanzador, el árbitro puede ponerse la máscara para observar los lanzamientos de calentamiento."},{"options":["De todas las decisiones del partido, incluidos los lanzamientos ilegales, las bolas fair/foul, las infracciones de bateo y los quietos y outs","Solo de bolas y strikes","Solo de las decisiones en home","Solo de las bolas fair/foul"],"q":"En el Sistema de Un Árbitro, ¿de qué decisiones es responsable el árbitro de home?","why":"Es evidente que no se verá todo lo que ocurra, por lo que el árbitro único debe moverse con determinación por el cuadro y dentro de él para obtener la mejor posición."}],"title":"Fundamentos - Mecánica de campo de un árbitro","nextLabel":"Continúa con el Módulo 03 - Mecánica de campo de dos árbitros"},"m03-mkc":{"questions":[{"options":["La pelota.","El marcador.","Los jugadores ofensivos.","Los jugadores defensivos."],"q":"Según el manual del Sistema de Dos Árbitros, ¿cuál de los siguientes NO es uno de los «Cuatro Elementos Esenciales» que el árbitro debe mantener a la vista sin obstáculos?","why":"Los Cuatro Elementos Esenciales son la pelota, los jugadores defensivos, los jugadores ofensivos y la base o la zona de la jugada."},{"options":["Los dos árbitros conjuntamente.","El árbitro de base.","El árbitro que llegue primero.","El árbitro de home."],"q":"Según el Principio de División, y salvo sus excepciones indicadas, ¿qué árbitro decide normalmente en home y en tercera base?","why":"El árbitro de home cubre normalmente home y tercera; el árbitro de base cubre normalmente primera y segunda. Las excepciones indicadas modifican esta división."},{"options":["Hacia el infield","Más hacia el outfield, hacia la pelota","A una posición sobre la línea de foul","Detrás de home"],"q":"Según el Principio Infield/Outfield, ¿hacia dónde se mueve el árbitro de base cuando la pelota se batea al outfield?","why":"Con la pelota en el outfield, el árbitro de base entra en el infield para mantener la jugada delante."},{"options":["El corredor adelantado es siempre el más rápido en base y necesita una supervisión más cercana","El árbitro de base debe empezar siempre lo más cerca posible de segunda, haya o no corredores","El árbitro de base se coloca en función del corredor adelantado porque se espera que el receptor intente un pickoff sobre ese corredor","El árbitro de home delega la cobertura del corredor adelantado para evitar el cansancio"],"q":"¿Cuál es la razón del Principio del Corredor Adelantado en el Sistema de Dos Árbitros?","why":"El pickoff esperado sobre el corredor adelantado determina la prioridad de la posición inicial del árbitro de base."},{"options":["4-5 metros (15 pies) detrás de la línea de base, en territorio fair","Justo detrás de la placa del lanzador, mirando hacia home","3,5 metros (10-12 pies) detrás de primera base, sobre la línea de foul","5,5 metros (18 pies) detrás de primera base en territorio foul, a 150 mm (6 pulgadas) de la línea"],"q":"Sin corredores en base, ¿cuál es la posición inicial del árbitro de base según el manual?","why":"Sin corredores, el árbitro de base empieza a unos 5,5 metros (18 pies) detrás de primera base en territorio foul y a 150 mm (6 pulgadas) de la línea."}],"title":"Fundamentos - Mecánica de campo de dos árbitros","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m03-pca":{"questions":[{"options":["El árbitro de home, porque es una jugada forzada.","El árbitro que esté más cerca de la base.","El árbitro de base.","El árbitro de home, porque la pelota bateada fue fair."],"q":"Sin corredores en base, el bateador batea un rodado normal al campocorto, que tira a primera. ¿Quién decide la jugada en primera?","why":"El árbitro de base entra en territorio fair, deja que la pelota lo oriente hacia la jugada y después se detiene, espera, decide y señala. La jugada en primera es del árbitro de base."},{"options":["Anticipar el doble play, moverse rápidamente hacia la base donde se hará la primera jugada y decidir todas las jugadas del primer tiro","Quedarse en posición de preparado en primera base hasta que termine el tiro","Ir de inmediato a tercera base para cubrir el avance de R1","Ceder la cobertura de primera base al árbitro de home"],"q":"Con un corredor en primera base, el bateador batea un rodado que puede convertirse en doble play. Según el manual, ¿qué debe hacer el árbitro de base?","why":"Anticipa el doble play y muévete hacia la base donde se producirá la primera jugada. Deja que la pelota te oriente hacia la jugada y después detente, espera, decide y señala."},{"options":["El árbitro de home","El árbitro de base","Los dos árbitros conjuntamente","Ninguno: en los fly atrapados no se juzgan los tag-ups"],"q":"Con un corredor en primera base, el bateador batea un fly al outfield que es atrapado. ¿Qué árbitro es responsable de la decisión del tag-up en primera?","why":"Con un corredor en primera y un fly al outfield, el árbitro de base entra en el diamante y se encarga del tag-up en primera. El árbitro de home juzga si la pelota es atrapada o no."},{"options":["El árbitro de home, porque la división normal siempre se aplica en tercera.","El árbitro que esté más cerca de home.","El árbitro que tenga en ese momento el ángulo más claro.","El árbitro de base, según la excepción indicada para el robo."],"q":"Con corredores en primera y segunda, el corredor que estaba en segunda intenta robar tercera en el lanzamiento. ¿Qué árbitro decide en tercera?","why":"Un robo de segunda a tercera es una excepción explícita a la división normal: decide el árbitro de base."},{"options":["El árbitro de base lleva al corredor que estaba en segunda hasta tercera y al bateador-corredor por primera, segunda y tercera; el árbitro de home vigila el tag-up en tercera y se prepara para una jugada en tercera o en home.","El árbitro de base lleva solo al bateador-corredor por primera y segunda; el árbitro de home se encarga de los dos corredores originales y del bateador-corredor en tercera.","El árbitro de base lleva al corredor que estaba en tercera hasta home; el árbitro de home lleva al bateador-corredor por todas las bases.","Los dos árbitros siguen al corredor que estaba en tercera y dejan que el bateador-corredor avance sin cobertura."],"q":"Con corredores en segunda y tercera, el bateador batea una pelota al outfield. ¿Qué reparto completo sigue la guía?","why":"La página 27 asigna al árbitro de base el corredor original de segunda en tercera, junto con el bateador-corredor hasta tercera. El árbitro de home vigila el tag-up en tercera y anticipa la acción en tercera o en home. Comunica cualquier desviación necesaria."},{"options":["El árbitro de base, porque todo primer tiro corresponde al árbitro de base.","El árbitro que esté más cerca del lanzador.","Los dos árbitros a la vez.","El árbitro de home, que anticipa y cubre la jugada en home."],"q":"Con las bases llenas, se fildea un rodado y el primer tiro va directamente a home para una jugada forzada. ¿Qué árbitro decide la jugada en home?","why":"El árbitro de home cubre home y debe anticipar la jugada allí. No interpretes la asignación del primer tiro al árbitro de base como una transferencia de la cobertura de home."},{"options":["El árbitro de home, ya que según el Principio de División las decisiones en tercera son siempre suyas","El árbitro de base","El árbitro que empezó la jugada más cerca de tercera","El árbitro de home, porque el árbitro de base solo cubre primera y segunda"],"q":"El bateador batea una pelota al outfield y, como bateador-corredor, avanza hasta tercera base. Según las excepciones al Principio de División, ¿quién decide sobre el bateador-corredor en tercera?","why":"El bateador-corredor que avanza hasta tercera es una excepción explícita a la división normal. El árbitro de base lleva al bateador-corredor por primera, segunda y tercera."},{"options":["A 5,5 metros (18 pies) detrás de primera base en territorio foul","Detrás y a un lado del segunda base, inclinado hacia primera","Detrás y a un lado del campocorto, inclinado hacia el corredor de segunda, con visión del lanzador, el corredor y la zona de home","En el césped del outfield detrás de segunda base"],"q":"Con un corredor solo en segunda base, y antes del lanzamiento, ¿dónde debe colocarse el árbitro de base?","why":"Con un corredor solo en segunda, el árbitro de base empieza detrás y a un lado del campocorto, inclinado hacia ese corredor, manteniendo la visión del lanzador, el corredor y la zona de home."},{"options":["Acercarse a unos 3,5 metros (10-12 pies) para ver y decidir la jugada","Quedarse a 5,5 metros (18 pies), ya que esa distancia vale para todas las decisiones","Moverse a 4-5 metros (15 pies) detrás de la línea de base","Retroceder más hacia territorio foul para tener un ángulo más amplio"],"q":"El árbitro de base está colocado para una posible jugada en primera y queda claro que el tiro exigirá un tag en lugar de un forzado. Según el manual, ¿qué ajuste debe hacer?","why":"La guía indica unos 5,5 metros (18 pies) para las jugadas forzadas y 3,5 metros (10-12 pies) para las jugadas de tag. Ajústate para la jugada de tag manteniendo delante los Cuatro Elementos Esenciales."},{"options":["El árbitro de base, ya que decide todas las jugadas, incluidos los tiros posteriores","Los dos árbitros deben decidirla a la vez","El árbitro que esté colocado en territorio fair","El árbitro de home, responsable de las jugadas siguientes en tercera o en home después de la primera jugada del infield"],"q":"Con corredores en primera y tercera, se batea un rodado al infield. La defensa hace la primera jugada (un forzado en segunda) y luego tira a home para intentar sacar al corredor de tercera. ¿Qué árbitro es responsable de decidir esta segunda jugada en home?","why":"Después de la primera jugada del infield, el árbitro de home cubre las jugadas siguientes en tercera o en home. En este caso el tiro a home es la jugada siguiente."},{"options":["El árbitro de home, porque tercera siempre le corresponde.","El árbitro de base, según la excepción para la primera decisión del infield en una base.","Los dos árbitros deben señalar.","Ningún árbitro hasta que se haga el siguiente tiro."],"q":"Con corredores en primera y segunda, el bateador batea un rodado y la defensa hace su primera jugada en tercera base. ¿Quién decide esa primera jugada en tercera?","why":"La primera decisión del infield en una base corresponde al árbitro de base aunque sea en tercera. El árbitro de home se prepara para las jugadas siguientes en tercera o en home."},{"options":["Quedarse detrás del receptor y dejar el fair/foul y la atrapada al árbitro de base.","Seguir al bateador-corredor hasta segunda sin decidir sobre el fly.","Moverse hacia la trayectoria de la pelota, ponerse a horcajadas sobre la línea para la decisión ajustada de fair/foul y juzgar si es atrapada o no.","Ir directamente a tercera base sin mirar la pelota."],"q":"Sin corredores en base, se batea un fly cerca de la línea de foul del jardín derecho. ¿Qué exige la guía al árbitro de home?","why":"El árbitro de home se mueve hacia la trayectoria de la pelota y juzga su estado. En una pelota cerca de la línea de foul, se coloca a horcajadas sobre la línea para la decisión de fair/foul. El árbitro de base lleva al bateador-corredor por las bases."},{"options":["Comunicar la desviación a tu compañero.","Suponer que tu compañero entenderá el cambio sin comunicación.","Cantar \"Tiempo\" de inmediato en cada desviación.","Seguir decidiendo tú todas las jugadas en ambas bases."],"q":"Una jugada en desarrollo te obliga a desviarte del reparto normal de la cobertura en el sistema de dos árbitros. ¿Qué debes hacer?","why":"La sección de excepciones exige expresamente comunicar cuando los árbitros deben desviarse. Una comunicación clara ayuda al equipo arbitral a mantener la cobertura y a evitar decisiones contradictorias."},{"options":["Un pie bastante más adelantado que el otro","Juntos, con el peso en los talones","Lo más separados posible","A una distancia cómoda, al menos al ancho de los hombros, relajado pero quieto"],"q":"Cuando el lanzador adopta la posición de set, ¿cómo debe colocar los pies el árbitro de base?","why":"Cuando el lanzador junta las manos, coloca los pies a una distancia cómoda, al menos al ancho de los hombros, y permanece relajado pero quieto. En el lanzamiento, desbloquea ligeramente las rodillas, con el peso suavemente sobre la parte delantera de los pies y las manos cerca del cinturón."},{"options":["Por la derecha, porque el bateador es zurdo.","Por el lado que lleve directamente hacia el movimiento del receptor.","Quedarse detrás del receptor hasta que todos los corredores lleguen a una base.","Por la izquierda, también cuando el bateador es zurdo."],"q":"El bateador es zurdo y batea la pelota. ¿Por qué lado del receptor exige la guía que salga el árbitro de home?","why":"La guía indica que en cada batazo el árbitro de home sale por la izquierda del receptor, incluso con un bateador zurdo, y luego va a la posición necesaria."},{"options":["Quedarse fuera de primera y dejar segunda y tercera al árbitro de home.","Entrar en el infield y prepararse para llevar al bateador-corredor en segunda y tercera.","Cantar \"Bola muerta\" solo porque el tiro se pasó.","Seguir la pelota hacia el outfield y abandonar al bateador-corredor."],"q":"Sin corredores en base al inicio, el tiro a primera tras un batazo al infield se escapa pero la pelota sigue en juego. El bateador-corredor avanza. ¿Qué debe hacer a continuación el árbitro de base?","why":"En un tiro desviado tras esta jugada del infield, el árbitro de base entra en el infield y se prepara para segunda y tercera. El enunciado indica que la pelota sigue en juego."},{"options":["Estar relajado","Mirar hacia home","Mantener una visión clara de home","Colocarse por delante de algún jugador de cuadro antes de que el receptor reciba el lanzamiento o se batee la pelota"],"q":"¿Qué NO debe hacer el árbitro de base al colocarse antes del lanzamiento?","why":"Antes de que el receptor reciba el lanzamiento o se batee la pelota, el árbitro de base no debe colocarse por delante de un jugador de cuadro y debe mantener una visión sin obstáculos de home."},{"options":["Ir a segunda base","Seguir al bateador-corredor aproximadamente un tercio del camino hacia primera, vigilando una posible interferencia u obstrucción","Ir directamente a tercera base","Quedarse detrás del plato"],"q":"En un batazo al infield sin corredores en base, ¿qué hace el árbitro de home?","why":"Sin corredores, en un batazo al infield el árbitro de home sigue al bateador-corredor aproximadamente un tercio del camino hacia primera, vigilando una posible interferencia u obstrucción y ayudando si hace falta."},{"options":["Justo fuera de la línea de tercera en territorio foul, aproximadamente a un tercio del camino hacia tercera","Justo fuera de la línea de primera, aproximadamente a un tercio del camino hacia primera","Detrás del receptor","En la placa del lanzador"],"q":"Entre entradas en el Sistema de Dos Árbitros, ¿dónde se coloca el árbitro de home?","why":"Entre entradas, el árbitro de home se coloca en territorio foul justo fuera de la línea de tercera, aproximadamente a un tercio del camino hacia tercera. El árbitro de base usa la posición equivalente en el lado de primera."},{"options":["Solo el árbitro de home","El árbitro que esté más cerca de la placa del lanzador","Los dos árbitros comparten la responsabilidad","Solo el árbitro de base"],"q":"En el Sistema de Dos Árbitros, ¿quién es responsable de cantar los lanzamientos ilegales?","why":"Los dos árbitros comparten la responsabilidad de los lanzamientos ilegales. El árbitro de home tiene además las responsabilidades indicadas de fair/foul e infracciones de bateo; las responsabilidades concretas sobre el lanzamiento se desarrollan en la guía de Fundamentos."}],"title":"Fundamentos - Mecánica de campo de dos árbitros","nextLabel":"Continúa con el Módulo 04 - Mecánica de campo de tres árbitros"},"m04-mkc":{"questions":[{"options":["La pelota, los jugadores defensivos, los jugadores ofensivos y la base o la zona de la jugada","La pelota, el lanzador, el receptor y la base","La pelota, el corredor, el entrenador y el marcador","La pelota, el fildeador, el dugout y la línea de foul"],"q":"Según los «Cuatro Elementos Esenciales» del manual del Sistema de Tres Árbitros, ¿qué cuatro cosas debe mantener el árbitro a la vista sin obstáculos para tener la jugada delante?","why":"Los cuatro elementos son la pelota, los jugadores defensivos, los jugadores ofensivos y la base o la zona de la jugada."},{"options":["El árbitro de base que queda","El árbitro de home","El árbitro que esté más cerca de tercera","Los dos árbitros conjuntamente"],"q":"Según el Principio de División general, salvo las excepciones indicadas y las instrucciones concretas de cada situación, ¿qué árbitro decide normalmente en home y en tercera cuando un árbitro de base sale a un fly?","why":"La división general asigna home y tercera al árbitro de home, y primera y segunda al árbitro de base que queda. Aplica las excepciones indicadas y las instrucciones detalladas de cada situación."},{"options":["Correr hasta el backstop para comprobar si hay interferencia","Indicar al receptor que se ponga de pie antes de cada lanzamiento","Dar un pequeño paso a la izquierda del árbitro de home para salir de detrás del receptor","Colocarse justo detrás del receptor para tener el mejor ángulo"],"q":"¿Qué significa «despejar al receptor» para el árbitro de home, según el manual del Sistema de Tres Árbitros?","why":"Despejar al receptor significa dar un pequeño paso a la izquierda del árbitro de home, creando espacio y abriendo la visión antes de que se desarrolle la jugada."},{"options":["En cuanto el lanzador adopta la posición de set","Durante la reunión previa al partido","Solo después de que la pelota esté en juego","Cuando el lanzador inicia el lanzamiento"],"q":"En la posición de preparado del árbitro de base que describe este manual, ¿cuándo debe el árbitro adoptar la posición de «preparado», desbloqueando ligeramente las rodillas y apoyando el peso en la parte delantera de los pies?","why":"Los pies se colocan cómodamente separados cuando el lanzador hace el set. Cuando el lanzador inicia el lanzamiento, desbloquea ligeramente las rodillas, con el peso suavemente sobre la parte delantera de los pies y las manos cerca del cinturón."},{"options":["Salir más allá de la línea de base para respaldar la jugada","Quedarse en posición de preparado en su base original","Rotar hacia el interior del diamante","Seguir la pelota hacia la cerca del outfield"],"q":"Según el Principio Infield/Outfield del Sistema de Tres Árbitros, ¿qué debe hacer un árbitro de base que NO sale a un fly una vez que la pelota está en el outfield?","why":"Los árbitros de base que no salen rotan hacia dentro cuando la pelota está en el outfield. Cuando un árbitro sale, el árbitro de base que queda debe rotar hacia dentro."}],"title":"Fundamentos - Mecánica de campo de tres árbitros","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m04-pca":{"questions":[{"options":["El árbitro de home, siguiendo al corredor hasta segunda","U1, que se queda en primera y cubre también segunda","U3, que rota a segunda en línea con el árbitro de home","U3 se queda en tercera y no rota"],"q":"Sin corredores en base, se batea un rodado al infield que da lugar a una posible jugada forzada en primera. Si el bateador-corredor es safe en primera y sigue hacia segunda, ¿qué árbitro ha rotado para decidir esa jugada, según el manual del Sistema de Tres Árbitros?","why":"U3 rota a segunda, en línea con el árbitro de home, preparado para decidir si el bateador-corredor es safe en primera y sigue hacia segunda."},{"options":["El árbitro de home","U3","U1 vuelve del outfield para encargarse del corredor","La cobertura se reparte a partes iguales entre el árbitro de home y U3"],"q":"Sin corredores en base, U1 sale a un fly al outfield. Si la pelota no es atrapada, ¿qué árbitro es responsable de llevar al bateador-corredor a segunda y hasta tercera?","why":"En esta situación concreta, U3 entra en el diamante y lleva al bateador-corredor a segunda y hasta tercera si la pelota no es atrapada. El árbitro de home ayuda primero en una posible jugada en primera y luego se prepara para home."},{"options":["Da un paso adelante hacia segunda para tener ángulo sobre el tiro","Va a tercera para cubrir un posible avance","Se queda en su posición de preparado original fuera de la línea de tercera","Sale hacia el outfield para respaldar el tiro"],"q":"Con un corredor en primera base, se batea un rodado al infield con posibilidad de doble play. ¿Qué hace U3 anticipando el tiro a segunda?","why":"U3 suele dar un paso adelante hacia segunda y ajustarse para tener el mejor ángulo sobre el tiro a segunda. U1 se prepara para la jugada siguiente en primera."},{"options":["U3","El árbitro de home","U1 y U3 comparten las decisiones","U1"],"q":"Con un corredor solo en segunda base, se batea un rodado al infield. ¿Qué árbitro es responsable de las decisiones tanto en primera como en segunda en esta situación?","why":"U1 se mueve hacia la jugada inicial y es responsable de primera y segunda. U3 se prepara para el corredor que avanza de segunda hacia tercera."},{"options":["U1","U3, después de soltar tercera","El árbitro de home, subiendo por la línea de primera","Ningún árbitro: la pelota está muerta"],"q":"Con un corredor solo en tercera base, se batea un rodado al infield. Si U3 no puede soltar a R1 en tercera (R1 no va hacia home), ¿qué árbitro puede tener que llevar al bateador-corredor a segunda y decidir la jugada?","why":"Si el corredor se queda en tercera y U3 no puede soltar esa cobertura, U1 puede tener que llevar al bateador-corredor a segunda. Lee a los corredores y las posiciones de los demás árbitros."},{"options":["U3","El árbitro de home","U1, antes de salir al outfield","Ningún árbitro vigila el tag-up en esta situación"],"q":"Con un corredor en tercera base, U1 sale a un fly. ¿Qué árbitro se mueve a la zona de espera entre home y tercera para vigilar el tag-up de R1, preparándose a la vez para una posible jugada en home?","why":"El árbitro de home usa la zona de espera entre home y tercera para observar el tag-up en tercera y después se mueve según haga falta para una jugada en tercera o en home. U3 entra en el diamante para cubrir al bateador-corredor."},{"options":["El árbitro de home vigila primera y segunda; U3 vigila tercera.","U3 vigila los tres tag-ups mientras el árbitro de home solo mira la atrapada.","El árbitro de home vigila el tag-up en tercera; U3 entra en el diamante y vigila los tag-ups en primera y segunda.","No hace falta observar los tag-ups hasta que la pelota sea atrapada."],"q":"Con las bases llenas, U1 sale a un fly dentro de la zona de cobertura de U1, lejos de la excepción de la línea del jardín derecho. ¿Cómo deben repartirse los demás árbitros la observación de los tag-ups?","why":"Cuando U1 sale en esta situación, el árbitro de home observa el tag-up en tercera y se prepara para la acción en tercera o en home. U3 entra en el diamante para observar primera y segunda. Observa el primer toque y el contacto de los corredores con sus bases."},{"options":["Se queda en tercera sea cual sea el avance de R1","Sigue a R1 hacia home","Rota de inmediato a primera base","Entra aproximadamente un paso en territorio fair, anticipando una jugada sobre R2, que avanza desde segunda"],"q":"Con corredores en segunda y tercera, se batea un rodado al infield. Si R1 (el corredor de tercera) avanza hacia home, ¿qué hace U3, según el manual?","why":"Si el corredor adelantado avanza hacia home, U3 entra en territorio fair para prepararse para el corredor que viene de segunda. Si el corredor adelantado se queda en tercera, U3 mantiene la cobertura de tercera."},{"options":["Primera base","Tercera base","El árbitro de home se queda en home","Segunda base, junto a U3"],"q":"Con un corredor en primera base, la pelota atraviesa el infield hacia el outfield y ningún árbitro sale. Mientras R1 avanza hacia segunda, ¿hacia dónde rota el árbitro de home para prepararse para una posible decisión?","why":"Mientras el corredor de primera avanza hacia segunda, el árbitro de home rota hacia tercera para una posible decisión. El equipo arbitral también debe mantener la cobertura de home mientras se desarrolla la rotación."},{"options":["Soltar para cubrir home","Volver más allá de la línea de base en territorio fair","Quedarse en la línea de foul a la altura de la base","Rotar hacia el interior del diamante"],"q":"Con un corredor en segunda base, la pelota atraviesa el infield hacia el jardín derecho. Según la nota del manual, si existe la posibilidad de una jugada en tercera con el tiro de vuelta, ¿qué debe hacer U3?","why":"En un batazo al jardín derecho o al centro-derecho, U3 puede leer la jugada desde cerca de la línea. Si es posible una jugada en tercera con el tiro de vuelta, rota hacia dentro. Si el tiro va a home sin jugada inmediata en tercera, la guía permite volver más allá de la línea de base en territorio fair."},{"options":["Automáticamente, sin comunicarse con el árbitro de home.","Solo si el árbitro del outfield vuelve para cubrir home.","Después de comunicar esa cobertura al árbitro de home.","Nunca; el árbitro de home debe encargarse de todos los corredores en tercera sin excepción."],"q":"Un árbitro de base ha salido y el fly es atrapado. El árbitro de base que queda entra en el diamante por delante del último corredor. Según la excepción indicada, ¿cuándo puede ese árbitro llevar al corredor hasta tercera?","why":"Tras un fly atrapado, el árbitro de base que queda y entra por delante del último corredor puede llevarlo hasta tercera, pero solo después de comunicarlo al árbitro de home."},{"options":["Mirar a sus compañeros y luego indicar y decir en voz alta «voy»","Esperar a que el árbitro de home decida sobre la pelota","Preguntar al entrenador","Salir corriendo directamente sin ninguna señal"],"q":"Antes de dar la espalda para salir a un fly, ¿qué debe hacer el árbitro?","why":"Observa la trayectoria de la pelota, establece contacto visual con los otros árbitros y luego indica y di en voz alta «Voy» antes de dar la espalda para encargarte del fly."},{"options":["Hacia el anotador","Hacia home","Hacia la pelota, después de detenerse, decidir y comunicar","Hacia el dugout"],"q":"¿Hacia dónde señalan los árbitros el out en un fly atrapado en el outfield?","why":"Detente, decide y comunica. Señala el out hacia la pelota. Haz la señal de no atrapada cuando la pelota se atrape a ras de suelo y haga falta; una no atrapada evidente no requiere una señal de safe rutinaria."},{"options":["Quedarse en el outfield hasta que termine toda la acción, pero seguir observando las jugadas del infield para poder ayudar si se lo piden","Volver de inmediato al infield","Ir a segunda base","Quedarse mirando solo el outfield"],"q":"Una vez que un árbitro ha salido al outfield, ¿qué debe hacer?","why":"El árbitro que sale se queda en el outfield hasta que termina toda la acción, sin dejar de observar lo que ocurre en el infield por si se necesita información en una consulta del equipo arbitral."},{"options":["Siempre el árbitro de primera base","El árbitro más cercano al dugout","Siempre el árbitro de home","El árbitro que está en el outfield; si ningún árbitro de base salió al outfield, el árbitro de home"],"q":"¿Quién señala un home run en el Sistema de Tres Árbitros?","why":"El árbitro del outfield señala el home run. Si ningún árbitro de base sale al outfield, esa responsabilidad corresponde al árbitro de home."},{"options":["El árbitro de segunda base, si lo hay","El árbitro de home","El entrenador","El jardinero más cercano"],"q":"Un árbitro de base, por error, no sale a un fly. ¿Quién decide?","why":"Si un árbitro de base no sale a un fly por error, decide el árbitro de home. Los árbitros de base pueden ayudar en las pelotas atrapadas a ras de suelo. Esto no obliga al equipo arbitral a abandonar el resto de su cobertura."},{"options":["Colocarse delante del campocorto para que el corredor quede detrás del árbitro.","Quedarse justo sobre la línea de foul y aceptar la visión tapada.","Ir detrás del receptor para compartir la visión del árbitro de home.","Trabajar en territorio foul detrás de tercera, hasta unos 2 metros (6 pies) de la línea de foul, para mantener una visión sin obstáculos de home y del bateador."],"q":"Con un corredor en tercera, el despegue del corredor tapa la visión de home a U3. ¿Qué ajuste de la posición inicial permite la guía?","why":"U3 debe evitar que lo tape el corredor que despega de tercera o que vuelve a ella. La posición inicial más abierta en territorio foul conserva la visión necesaria para las situaciones de pelota muerta y para ayudar en los swings a medias."},{"options":["Detrás del receptor","En el extremo del cajón de bateo del diestro que da al infield","En el extremo del cajón de bateo del zurdo que da al infield, mirando hacia la red de fondo","En primera base"],"q":"En la reunión previa al partido en el Sistema de Tres Árbitros, ¿dónde se coloca U1?","why":"U1 se coloca en el extremo del cajón de bateo del zurdo que da al infield, mirando hacia la red de fondo. U3 ocupa la posición equivalente en el cajón de bateo del diestro."},{"options":["U3","Quien esté más cerca del dugout","El árbitro de home","U1"],"q":"Después del tercer out sin corredores en base, ¿quién limpia la placa del lanzador camino de las líneas de base?","why":"Normalmente limpia la placa del lanzador el árbitro de base más cercano. Sin corredores, o si los dos árbitros de base están a la misma distancia, se encarga U3."},{"options":["Quedarse quieto y deducir el tag por la reacción del corredor.","Ajustarse para mantener a la vista los Cuatro Elementos Esenciales, incluso entrando en territorio foul si es necesario, sin perder de vista el borde de entrada.","Colocarse justo detrás del fildeador, de modo que la zona del tag quede oculta.","Ignorar el borde de entrada y mirar solo el guante."],"q":"En un tag de vuelta en primera base, la posición inicial no da a U1 una visión clara del tag y del borde de entrada. ¿Qué ajuste permite la guía?","why":"El tiro de vuelta a primera suele acabar en un tag de barrido. La guía permite una posición en territorio foul cuando hace falta para mantener delante los Cuatro Elementos Esenciales, pero U1 debe seguir viendo el borde de entrada. Ajústate a medida que se desarrolla la jugada."}],"title":"Fundamentos - Mecánica de campo de tres árbitros","nextLabel":"Continúa con el Módulo 05 - Apéndice 4: Filosofías de posicionamiento de élite"},"m05-mkc":{"questions":[{"options":["La posición del árbitro, la velocidad del corredor, el ruido del público y el marcador","El lanzador, el receptor, el bateador y el plato","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La posición inicial, la posición de decisión, el punto focal y el borde de entrada"],"q":"Según los Conceptos Clave y el Glosario del Apéndice 4, ¿cuáles son los «Cuatro Elementos Esenciales» que un árbitro debe observar juntos para tomar una decisión precisa?"},{"options":["Una distorsión visual que se produce cuando el árbitro ve una jugada desde un mal ángulo que impide separar con claridad los elementos de la jugada y su momento","Una infracción que se produce cuando el pie de apoyo del lanzador cae fuera del carril de lanzamiento","El retraso entre que un árbitro ve una jugada y señala una decisión","Un error de mecánica causado por empezar demasiado lejos de la base"],"q":"En los Conceptos Clave y el Glosario del Apéndice 4, ¿cómo se define el «Error de Paralaje»?"},{"options":["Directamente sobre la línea de foul, a la altura de primera base","A unos 3-4 metros (10-12 pies) directamente detrás de home, alineado con el eje central del plato","Dentro del diamante, a mitad de camino entre home y la placa del lanzador","En el Ángulo Diagonal de Segunda Base, a 3-4 metros detrás de segunda base"],"q":"¿Dónde se encuentra por lo general la Posición del Punto del Plato (POP)?"},{"options":["Ver - Moverse - Reaccionar - Dictaminar","Posicionarse - Seguir - Juzgar - Señalar","Observar - Esperar - Confirmar - Anunciar","Parar - Ver - Decidir - Señalar"],"q":"¿Qué secuencia disciplinada identifica el Apéndice 4 como la técnica que usan los árbitros para evitar la anticipación y el sesgo cognitivo antes de tomar y comunicar una decisión?"},{"options":["El Apéndice 4 sustituye al Apéndice 5 para los árbitros por debajo del nivel de élite","El Apéndice 4 y el Apéndice 5 cubren el mismo contenido en formatos distintos","El Apéndice 4 aporta el porqué; el Apéndice 5 aportará el cómo","El Apéndice 4 es solo para entrenadores, mientras que el Apéndice 5 es solo para árbitros"],"q":"¿Cómo describe el Apéndice 4 su relación con el Apéndice 5?"}],"title":"Apéndice 4: Filosofías de posicionamiento de élite","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m05-pca":{"questions":[{"options":["La señalización anticipada, porque el árbitro preparó la señal antes de que empezara la jugada","El sesgo de confirmación, porque fijarse en la acción del tag puede hacer que el cerebro confirme prematuramente un out y anule la relación real entre la pelota, el corredor y la base","El error de paralaje, porque el árbitro estaba colocado demasiado lejos de la jugada","Un incumplimiento de las responsabilidades primarias, porque el árbitro no rotó a la base correcta"],"q":"Durante una jugada de tag muy ajustada en tercera base, el árbitro ve claramente que el guante del fildeador toca la pierna del corredor, pero no sigue con claridad si la mano del corredor ya había llegado a la base. El árbitro declara out al corredor solo por el contacto del guante. ¿Qué principio del Apéndice 4 explica mejor el riesgo de este proceso de decisión?"},{"options":["No preocupa, porque la posición de slot del árbitro de home está alineada con todas las partes del campo","El árbitro de home debería dictaminar la jugada recordando la ubicación del lanzamiento y no la bola bateada","Solo preocupa para los juicios de jonrón, no para las líneas duras cerca de una base","El paralaje puede hacer que la pelota parezca fair o foul de forma errónea desde detrás del plato; la mecánica exige que el árbitro esté en la línea de foul para juzgar la jugada con precisión"],"q":"Una línea dura pasa cerca de la base de tercera. El árbitro de home, colocado detrás del receptor, es el único árbitro con vista de la jugada. Según la explicación del error de paralaje del Apéndice 4, ¿por qué preocupa esta posición y qué exige la mecánica correcta?"},{"options":["Permanecer fijo en el Ángulo Diagonal de Segunda Base sin importar cómo se desarrolle la jugada, ya que es la referencia inicial designada","Moverse de inmediato a la posición del Punto del Plato para obtener un mejor ángulo","Ajustar su posición a lo largo de la diagonal o salirse de ella según sea necesario, ya que la prioridad es siempre mantener una vista sin obstrucciones de los elementos clave","Pedir tiempo y reposicionarse solo después de que termine la jugada"],"q":"Un corredor que intenta evitar un tag de barrido en segunda base se desliza hacia la esquina trasera de la base, lejos de la posición del árbitro en el Ángulo Diagonal de Segunda Base. ¿Qué indica el Apéndice 4 que debe hacer el árbitro en esta situación?"},{"options":["El árbitro estaba en la posición equivocada o no esperó a que la jugada se desarrollara correctamente","El corredor cometió interferencia y debe ser declarado out automáticamente","El árbitro anticipó correctamente la jugada y debería mantenerse firme la próxima vez","Es una parte normal e inevitable de la mecánica de élite que no requiere ningún ajuste"],"q":"En una posible jugada de tag, un corredor corre directamente hacia el árbitro, obligándolo a moverse de repente para evitar una colisión. ¿Qué dice el Apéndice 4 que indica esta situación?"},{"options":["No decir nada, porque solo el árbitro de home tiene autoridad para dictaminar un lanzamiento ilegal","Esperar a la siguiente entrada para plantear el asunto al árbitro de home en privado","Si está seguro, dictaminar el lanzamiento ilegal, ya que la mecánica de la WBSC permite al árbitro cercano a segunda base controlar el pie de apoyo cuando está completamente fuera del carril de lanzamiento","Avisar discretamente al árbitro de home, pero nunca dictaminar la infracción directamente"],"q":"Durante un partido, el árbitro situado cerca de segunda base ve con claridad y sin dudas que el pie de apoyo del lanzador cayó completamente fuera del carril de lanzamiento, mientras que el ángulo del árbitro de home no le permite ver con claridad la infracción. Según el Apéndice 4, ¿qué debe hacer el árbitro cercano a segunda base?"},{"options":["Altera el momento de decisión y favorece las decisiones prematuras, porque el cerebro deja de procesar los elementos finales de la acción","No afecta a la precisión, ya que los árbitros con experiencia pueden hacer varias cosas a la vez con eficacia","Mejora el tiempo de reacción y es una técnica recomendada para las jugadas muy ajustadas","Solo afecta a las decisiones de bolas y strikes, no a las jugadas de tag"],"q":"Un árbitro empieza a formar mentalmente su señal de «out» mientras el fildeador aún está completando el intento de tag, antes de que la jugada haya terminado del todo. Según el Apéndice 4, ¿cuál es la consecuencia probable de este hábito?"},{"options":["U2 debe salir primero porque U2 tiene la posición inicial más central","Ambos árbitros deben salir a la vez para cubrir doblemente la jugada","Ningún árbitro debe salir; el árbitro de home debe cubrir todos los fly convergentes","U1 debe tener la primera oportunidad de salir, ya que U2 debe dar a U1 o a U3 la primera oportunidad y solo salir si ninguno lo hace"],"q":"En un sistema de cuatro árbitros, se batea un fly al hueco donde se superponen las zonas de cobertura de U1 y U2, y U1 también converge sobre la pelota. Según el Apéndice 4, ¿qué árbitro debe salir primero?"},{"options":["Los pies activos, que se usan únicamente para mantener el equilibrio mientras se está quieto","La técnica de la instantánea mental, en la que el árbitro toma una «fotografía mental» desde el ángulo inicial y otra desde el ángulo mejorado, y las combina en una imagen 3D más clara de la jugada","La corrección de paralaje, que elimina la necesidad de cambiar de posición","El principio del borde de entrada, que exige que el árbitro permanezca en todo momento a 90 grados de la trayectoria del corredor"],"q":"El ángulo inicial de un árbitro en una jugada de tag que se desarrolla es malo, pero el árbitro se mueve con decisión hacia un mejor ángulo cuando llega el tiro. ¿Qué técnica descrita en el Apéndice 4 refleja esto y cuál es su finalidad?"},{"options":["La posición más lejana con el ángulo limpio, porque en todos los casos los ángulos tienen prioridad sobre la distancia","La posición más cercana, porque la proximidad siempre produce el juicio más preciso","Ninguna; el árbitro debe pedir una revisión por video","La posición más cercana, porque la distancia tiene prioridad sobre el ángulo en la cobertura del outfield"],"q":"Un árbitro de base en un sistema de 3 o 4 árbitros debe decidir si sale a un fly. Una posición disponible está más cerca de la jugada, pero ofrece una línea de visión comprometida; otra está más lejos, pero ofrece un ángulo limpio y sin obstrucciones. ¿Qué elección refleja el principio del Apéndice 4 para las decisiones de cobertura del outfield?"},{"options":["Las Responsabilidades Primarias, porque el árbitro siempre debe rotar primero a otra base","El Posicionamiento y los Ajustes Dinámicos, porque no existe una posición «X marca el lugar»: las posiciones inicial y de observación nunca deben darse por la posición final de decisión","La Preparación Previa al Lanzamiento y la Cobertura del Outfield, porque el árbitro no anticipó la profundidad de los jardineros","El Error de Paralaje, porque el árbitro estaba alineado con el plano equivocado"],"q":"Un árbitro en formación trata su posición inicial de manual en segunda base como la posición desde la que debe hacerse cada decisión, incluso cuando un tiro y un tag llevan la jugada hacia el borde de entrada. ¿Qué principio clave del Apéndice 4 no refleja este enfoque?"},{"options":["Contar los lanzamientos de cada turno al bate","Memorizar la postura del bateador antes de cada lanzamiento","Tomar una foto con el teléfono después de la jugada","Tomar una fotografía mental de la jugada desde el ángulo inicial, moverse rápido a un mejor ángulo, tomar una segunda fotografía y combinarlas en una imagen 3D más clara"],"q":"¿Qué es la técnica de la «fotografía mental» que describe el Apéndice 4?","why":"El buen criterio nace de reunir la mayor cantidad posible de información visual; obtener el ángulo correcto suele importar más que la proximidad física."},{"options":["Señalar, ver la jugada, decidir, detenerse","Ver la jugada, señalar, decidir, procesar la jugada","Detenerse, ver la jugada, procesar la jugada, decidir, señalar","Decidir, detenerse, señalar, ver la jugada"],"q":"¿Qué secuencia da el Apéndice 4 para el buen momento de decisión en una jugada?","why":"Preparar la señal antes de que termine la jugada desvía la atención del cerebro de los elementos finales de la acción y fomenta cantar demasiado pronto."},{"options":["Que el árbitro se mueva demasiado pronto al borde de entrada","Que el árbitro pierda la cuenta","Que el cerebro «afirme» prematuramente un out porque ve el contacto del guante con el corredor, anulando la relación entre la pelota, el corredor y la base, por ejemplo que el corredor ya está tocando la base","Que el árbitro vea la pelota demasiado bien"],"q":"Según el Apéndice 4, ¿cuál es el riesgo de fijarse solo en la acción del tag?","why":"Un mal ángulo o el paralaje combinados con el sesgo de afirmación aumentan la probabilidad de una decisión incorrecta; cuando los ojos no están alineados con la jugada, el cerebro rellena la información que falta, a menudo de forma errónea."},{"options":["Solo cuando el árbitro de home se lo pide","Siempre que el pie toque el borde del carril","Solo en la primera entrada","Cuando el pie de avance cae totalmente fuera del carril de lanzamiento y la infracción es clara y evidente"],"q":"Según el Apéndice 4, ¿cuándo puede el árbitro cercano a segunda base cantar un lanzamiento ilegal por el pie de avance del lanzador?","why":"Solo el pie de avance debe caer dentro del carril de lanzamiento. El criterio para sancionar es que sea claro y evidente; el ajuste para verlo es temporal y no debe comprometer las responsabilidades principales."},{"options":["El árbitro de home desde detrás del receptor","Un árbitro situado en la línea de foul con una vista sin obstáculos del poste de foul","Cualquier árbitro dentro del cuadro","El árbitro cercano a segunda base"],"q":"Según el Apéndice 4, ¿quién puede juzgar con precisión si un fly profundo pasa por dentro o por fuera del poste de foul?","why":"Añadir distancia, o mirar desde dentro del cuadro, aumenta el error de paralaje; un árbitro cercano a segunda base está en un ángulo que distorsiona el juicio."},{"options":["La parte interior y la superior; la esquina exterior y la parte inferior son más difíciles de juzgar","La parte exterior y la inferior; la interior y la superior son más difíciles de juzgar","Solo el centro del plato","Todas las partes por igual"],"q":"Desde el slot, ¿qué partes de la zona de strike dice el Apéndice 4 que el árbitro de home ve con más claridad?","why":"Los ojos del árbitro de home están alineados con los planos interior y superior; para los lanzamientos exteriores y bajos, el punto de suelta del lanzador y el movimiento del guante del receptor aportan información adicional."},{"options":["Sobre la propia base","A aproximadamente 3-4 m (10-12 pies), dentro de la zona formada por el Ángulo Diagonal de Segunda Base y la extensión de la línea de tercera base","A aproximadamente 8-10 m (26-33 pies) directamente detrás de la base","A aproximadamente 1 m (3 pies), junto a la base"],"q":"Según el Apéndice 4, ¿a qué distancia detrás de segunda base está la posición inicial estándar de U2 o U3 en segunda base?","why":"Esta posición establece un punto de observación proactivo y permite al árbitro moverse con eficiencia alrededor de la base; empezar más lejos aumenta el arco de movimiento."},{"options":["Solo en los batazos que pasan la cerca","Solo cuando se lo pide el árbitro de home","En cualquier batazo que pueda ser atrapado por un jardinero de su zona de cobertura, que exija una decisión fair/foul en el jardín o que pueda ser jonrón","Solo en los batazos que son atrapados"],"q":"Según el Apéndice 4, ¿en qué batazos debe salir un árbitro de base en un sistema de 3 o 4 árbitros?","why":"En todos los casos, los ángulos tienen prioridad sobre la distancia."},{"options":["Se mueve hacia el interior para cubrir primera y segunda base, lo que reduce la necesidad de una rotación completa del equipo","Sale también","Se queda en segunda base","Rota a home"],"q":"En un sistema de Cuatro Árbitros, ¿qué hace U2 cuando U1 sale a un fly hacia la zona del jardín derecho?","why":"Que U1 salga en los batazos al jardín derecho mejora la cobertura de las bases más cercanas a home."},{"options":["U3 se encarga de todo el jardín","U1 se encarga de todo el jardín","El árbitro de home se encarga de todos los fly","Se divide por la mitad: U1 sale del jardín central a la línea de foul del jardín derecho y U3, del jardín central a la línea de foul del jardín izquierdo"],"q":"En un sistema de Tres Árbitros con U1 en primera base y U3 en tercera base, ¿cómo se divide el jardín para salir?","why":"Si un árbitro empieza en segunda base, la división cambia: el árbitro de home cubre los fly desde el jardinero izquierdo (o el derecho) hasta la línea de foul."}],"title":"Apéndice 4: Filosofías de posicionamiento de élite","nextLabel":"Continúa con el Módulo 06 - Apéndice 5: Mecánica de campo de élite"},"m06-mkc":{"questions":[{"options":["El lanzador, el receptor, el bateador y el árbitro de base","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La zona de strike, el despegue del corredor, el tag y el guante del fildeador","La posición inicial, la posición de observación, la posición de decisión y la base"],"q":"En la Teoría de los Cuatro Elementos Esenciales (FEET) del Apéndice 5a, ¿cuáles son los cuatro elementos que los árbitros deben observar a la vez para tomar una decisión correcta?","why":"La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada deben verse a la vez, incluido el control de la pelota y la relación entre el tag y la base."},{"options":["1-2 metros (3-6 pies)","6-12 metros (20-40 pies)","3-5 metros (9-15 pies)","2-4 metros (6-12 pies)"],"q":"Según el Apéndice 5a, ¿aproximadamente a qué distancia detrás de home se encuentra la posición Point of Plate (POP)?","why":"El POP es una zona situada aproximadamente a 2-4 metros detrás de home, no un punto fijo de decisión. Úsalo cuando tus funciones principales lo permitan y ajústate a medida que se desarrolla la jugada."},{"options":["A un árbitro que despeja al receptor para tener una visión sin obstáculos del campo","A un árbitro que se mueve al borde de entrada de una base para juzgar una jugada de tag","A un árbitro que contrarrota para cubrir una posición que no ocupa otro árbitro, porque este debe cubrir una jugada en otro lugar","A un árbitro que vuelve a su posición entre entradas cuando termina una jugada"],"q":"Según el Apéndice 5a, ¿a qué se refiere el «Backfilling»?","why":"En el backfilling un árbitro contrarrota hacia una cobertura que ha quedado libre porque otro árbitro debe cubrir una jugada en otro lugar. Lee la jugada y comunícate."},{"options":["Permitir que dos árbitros de outfield dedicados cubran los fly, de modo que los demás árbitros puedan quedarse en el infield y cubrir las bases en todo momento","Sustituir al árbitro de home por dos árbitros de outfield adicionales","Eliminar la necesidad de rotaciones entre bases","Permitir que todos los árbitros trabajen exclusivamente desde territorio foul"],"q":"¿Qué finalidad atribuye el Apéndice 5a al uso de los Sistemas de Cinco y Seis Árbitros?","why":"La cobertura dedicada del outfield permite a los demás árbitros mantener la cobertura del infield y de las bases, sobre todo en tercera y en home. Esta finalidad se indica en el propio Apéndice 5a; aquí no se evalúa la mecánica detallada de estos sistemas."},{"options":["Ofrecer una zona de observación flexible en territorio foul desde la que el árbitro lee qué base, 3B o HP, necesita cobertura y puede moverse hacia ella.","Sustituir todas las responsabilidades de rotación por un punto fijo de decisión.","Hacer que U1 espere cerca de primera en lugar de completar una rotación obligatoria a home.","Mantener al árbitro de home en una posición desde la que pueda decidir en ambas bases a distancia."],"q":"¿Cuál es la finalidad de la posición de espera que describe el Apéndice 5a?","why":"La posición de espera es una zona ovalada que permite observar activamente y ajustarse. Puede estar más cerca de la jugada probable sin dejar de permitir el movimiento hacia la otra base si hace falta."}],"title":"Apéndice 5: Mecánica de campo de élite","nextLabel":"Continúa con las presentaciones - Apéndice 5, Parte A: Conceptos clave"},"m06-pca":{"questions":[{"options":["Mantener la visión original y juzgar solo si el tiro llegó primero.","Mirar solo al corredor, porque la pelota y la posesión del fildeador pueden suponerse con la visión periférica.","Leer el cambio en la jugada, ajustarte de forma controlada para ver la relación entre pelota-guante, tag, corredor y base, y juzgar la jugada completa cuando todos los elementos confluyen antes de señalar.","Colocarte directamente sobre la base para acortar la visión, ya que se prefiere el ángulo a la distancia."],"q":"Estás preparado para juzgar una jugada forzada cuando el fildeador deja la base para atrapar un tiro desviado e intenta un tag de barrido. ¿Qué debes hacer?","why":"Un tag que se desarrolla puede requerir un ángulo distinto del de la visión inicial de la jugada forzada. Mantén a la vista los cuatro elementos, incluido el control y el toque de la base, en lugar de suponer que la posición de decisión original sigue siendo suficiente."},{"options":["El error de paralaje se debe sobre todo a la distancia. Acercarse mejora el juicio sea cual sea el ángulo, siempre que el árbitro vea al corredor y al fildeador.","Un ángulo de visión inadecuado puede distorsionar la relación entre el corredor, la base y el punto del tag. Una mayor distancia puede agravarlo, y la alineación de todos los elementos en línea recta es lo que causa la mayor pérdida de separación visual.","El error de paralaje solo se produce cuando los elementos están completamente alineados. Hasta entonces, el árbitro puede juzgar la secuencia con precisión sin ajustar su posición.","Permanecer quieto en la posición de observación original evita el error de paralaje. Moverse durante la jugada cambia la perspectiva y hace menos fiable la secuencia, incluso cuando la visión original queda parcialmente bloqueada."],"q":"Según el Apéndice 5a, ¿cuándo se produce con más frecuencia el error de paralaje?","why":"El error de paralaje puede afectar al juicio antes de que el árbitro quede completamente alineado. Un ángulo inadecuado puede distorsionar la relación aparente entre el corredor, la base y el punto del tag, y una mayor distancia puede agravar el problema. La alineación en línea recta es especialmente peligrosa porque los elementos se superponen, lo que reduce la percepción de profundidad y puede ocultar si el corredor tocó la base antes del tag. Usa el borde de entrada cuando te dé la visión necesaria y ajústate de forma deliberada para mantener un ángulo sin obstáculos y la separación visual."},{"options":["Situarse lo más atrás posible para ver todo el campo","Confiar en que el árbitro de base tome la decisión","Esperar a que la pelota se detenga antes de decidir","Colocarse en el plano de la decisión, por ejemplo sobre la línea de fair/foul"],"q":"Un árbitro quiere eliminar el error de paralaje en una decisión de fair/foul. ¿Qué dice el Apéndice 5a que debe hacer?","why":"En una decisión de fair/foul, colócate sobre la línea de fair/foul correspondiente para juzgar la pelota directamente respecto a ese plano. Puede que sigan siendo necesarios ajustes de momento y de ángulo para otros elementos de la jugada."},{"options":["Empezar en el lado de 1B o estar preparado para moverse hacia el lado de primera de la 2BDA, manteniendo una visión sin obstáculos de home y del bateador, para poder entrar rápidamente en el diamante y cubrir una posible jugada en primera.","Usar la posición alternativa del lado de tercera para tener el mejor ángulo sobre un posible pickoff en segunda y cruzar luego el diamante si hace falta cubrir primera.","Empezar más atrás de segunda en la 2BDA para tener una visión más amplia del outfield, aceptando el movimiento adicional necesario para establecer una posición de decisión en primera.","Empezar hacia la prolongación de la línea de tercera para dar prioridad al corredor que avanza a tercera, dejando primera a cargo de U1 hasta que termine la jugada del outfield."],"q":"Con un corredor en segunda, el árbitro que trabaja en la 2BDA puede tener que cubrir primera si U1 sale. ¿Qué posición inicial prefiere el Apéndice 5a?","why":"Con un corredor en segunda, empezar en el lado de 1B, el lado preferido o ligeramente hacia el lado de primera de la 2BDA, ayuda al árbitro a entrar en el diamante y cubrir primera si U1 sale. La posición debe seguir dando una visión sin obstáculos de home y del bateador y permitir al árbitro establecer el ángulo y la distancia necesarios para la jugada en desarrollo. Así U2 no tiene que preocuparse por el despegue del corredor desde 2B."},{"options":["Unos 3 m (10 pies) para una jugada forzada y 5 m (16 pies) para una jugada de tag","Unos 5 m (16 pies) para una jugada forzada y 3 m (10 pies) para una jugada de tag","Unos 5 m (16 pies) para ambas","Unos 3 m (10 pies) para ambas"],"q":"En una jugada, ¿qué distancia a la base indica el Apéndice 5a para una jugada forzada y para una jugada de tag?","why":"El Apéndice 5a indica aproximadamente 5 metros para una jugada forzada y 3 metros para una jugada de tag. Son distancias de trabajo, no las distancias iniciales previas al lanzamiento. El ángulo tiene prioridad cuando ángulo y distancia no pueden ser ideales a la vez; conserva margen para ajustarte y llegar al borde de entrada."},{"options":["Entrar en el diamante y hacer el button-hook girando sobre el hombro izquierdo, conservando la visión y la flexibilidad para la cobertura necesaria.","Mantener el pie derecho fijo en primera y girar solo la parte superior del cuerpo.","Seguir la pelota hacia el outfield sin comprobar al corredor ni al equipo arbitral.","Quedarse en territorio foul aunque eso impida cubrir la base necesaria."],"q":"U1 necesita entrar en el diamante para cubrir varias bases y seguir pudiendo adaptarse a una decisión tardía de salir o a un backfill. ¿Qué técnica sigue el Apéndice 5a?","why":"El button-hook gira sobre el hombro izquierdo después de entrar en el diamante. Facilita cubrir varias bases y adaptarse a un cambio de rotación, a un backfill o a la decisión tardía de un compañero. U2 también lo usa en el ejemplo de cuatro árbitros cuando U1 sale."},{"options":["Porque coloca al árbitro demasiado cerca para seguir el tiro hasta el guante, así que la posición de decisión debe mantenerse a la distancia de una jugada forzada aunque se desarrolle un tag.","Porque impide al árbitro mantener un ángulo de 90 grados respecto al tiro, que debe mantenerse en todas las jugadas forzadas y de tag.","Porque limita la visión del árbitro sobre las jugadas secundarias, así que la posición de decisión debe dar prioridad al siguiente tiro posible antes que al tag y al toque de la base.","Porque alinea verticalmente los ojos del árbitro con la base, lo que hace que la pelota, el tag y el borde de entrada se superpongan, reduce la percepción de profundidad y hace más difícil juzgar el momento."],"q":"¿Por qué dice el Apéndice 5a que el árbitro nunca debe colocarse directamente sobre una base al decidir?","why":"Decidir directamente sobre la base puede reducir los elementos a una visión alineada en línea recta. Esto reduce la separación visual y puede distorsionar si el corredor tocó la base antes del tag. Una posición justo antes del borde de entrada, con el ángulo, la profundidad y el ajuste adecuados, ayuda al árbitro a ver con claridad cómo confluyen los elementos."},{"options":["Todos los árbitros de base deben quedarse fuera siempre que nadie salga.","U2 debe pedir tiempo antes de elegir una posición.","U2 puede quedarse fuera en ese caso; si un árbitro sale, los demás árbitros de base deben entrar en el diamante para la cobertura y el backfill.","U2 puede quedarse fuera incluso cuando un compañero sale y se necesita cobertura interior."],"q":"Se batea una pelota al outfield y ningún árbitro sale. U2 puede mantener delante los Cuatro Elementos Esenciales desde fuera. ¿Qué afirmación aplica correctamente el Apéndice 5a?","why":"Entrar en el diamante es la respuesta habitual cuando la pelota está en el outfield. La sección 5a permite expresamente a U2 quedarse fuera si los cuatro elementos siguen delante y nadie sale. Cualquier situación en la que un árbitro sale obliga a los demás árbitros de base a entrar para la cobertura y, en particular, para el backfill."},{"options":["El árbitro que queda, U2 o U3, cubre tercera; U1 entra en el diamante para cubrir primera y segunda si es posible, con una posición alternativa y un ajuste del equipo arbitral si entrar interfiriera en el juego.","Los dos árbitros de base que quedan permanecen en segunda hasta que termina la jugada en home.","Ordenar al árbitro de home que deje home y vaya a tercera aunque la jugada sea en home.","Exigir que U1 entre en el diamante aunque al hacerlo interfiera con un corredor o un tiro."],"q":"En el ejemplo de backfill de cuatro árbitros, U2 o U3 sale y el árbitro de home comunica que se queda en home para una jugada. ¿Qué deben hacer los demás árbitros de base?","why":"La comunicación del árbitro de home sobre la cobertura de home activa este ejemplo. El U2/U3 que queda hace el backfill a tercera. Si U1 no puede entrar sin interferir, U1 se desplaza hacia la cerca cerca del dugout de primera y el compañero tiene en cuenta una posible cobertura de segunda."},{"options":["Cantar safe al corredor","Cantar out al corredor, porque aún está procesando la recepción del tiro","Cantar interferencia","No ver la base"],"q":"En una jugada forzada ajustada en la que el corredor llega a la base y después el fildeador recibe el tiro, ¿qué error es más probable que cometa un árbitro que mira el tiro o se precipita en la decisión, según el Apéndice 5a?","why":"En la secuencia indicada el corredor es safe, pero un árbitro que se precipita puede reaccionar a la recepción posterior y cantar out. Una breve pausa permite procesar todos los datos en orden antes de decidir y comunicar."},{"options":["Esperar en la antigua zona de espera de primera hasta que el corredor llegue a primera.","Detenerse en la prolongación de la línea de tercera en cada posible tag de barrido.","Soltar primera sin observar el tag-up o el toque de base necesarios y dejar que el equipo arbitral adivine la rotación.","Completar la observación necesaria en primera, aunque sea mirando por encima del hombro, soltar rápidamente, comunicar para empujar al árbitro de home hacia tercera y moverse hacia el POP sin una demora innecesaria en la zona de espera."],"q":"U1 debe rotar a home mientras avanza el corredor adelantado. ¿Qué enfoque sigue la prioridad de cobertura de home del Apéndice 5a?","why":"El corredor adelantado y la cobertura de home tienen prioridad. Observa los tag-ups necesarios y el toque de primera del bateador-corredor, también por encima del hombro derecho cuando corresponda, y después rota rápidamente. La antigua zona de espera de U1 en primera se omite y queda solo como punto de referencia porque retrasa la cobertura de home. El POP es una referencia de observación flexible, no una decisión final fija."},{"options":["Que el árbitro trota en el sitio entre lanzamientos para no enfriarse","Que el árbitro da pasos cortos y rápidos mientras la pelota está en el aire","Que el árbitro mueve ambos pies al ajustar su posición para mantenerse equilibrado sobre la parte delantera de los pies y preparado para moverse","Que el árbitro mantiene un pie fijo hasta tomar la decisión"],"q":"¿Qué quiere decir el Apéndice 5a con «pies activos»?","why":"Mueve ambos pies siempre que puedas para mantenerte equilibrado sobre la parte delantera de los pies y preparado para ajustarte. Esto no significa moverse sin necesidad: quédate quieto si la visión es estable y clara; ajústate cuando la visión del tag se estreche o quede bloqueada, controlando la cabeza y la vista."},{"options":["Con un corredor en primera o corredores en primera y tercera, unos 3,5 metros atrás en el lado de primera de la 2BDA, lo que ofrece una ruta directa hacia dentro para cubrir primera.","Con un corredor en segunda o corredores en segunda y tercera, unos 3,5 metros atrás en la zona alternativa del lado de tercera, dando prioridad a ver al corredor que vuelve a segunda.","Con un corredor en primera o corredores en primera y tercera, unos 3,5 metros atrás, justo al lado de la 2BDA en el lado de tercera, siempre que el bateador y home sigan visibles y se conserve el acceso al borde de entrada y a la cobertura interior necesaria.","Con un corredor en primera o corredores en primera y tercera, unos 3,5 metros atrás hacia la prolongación de la línea de primera, usando la base como referencia de alineación para el tag previsto."],"q":"Un árbitro se plantea usar la posición inicial alternativa en segunda en lugar del lado preferido, el de 1B, de la 2BDA. Debe tener en cuenta si el bateador es diestro o zurdo y la trayectoria de salida del lanzador, que puede tapar la visión del bateador y de la zona de home. ¿Qué descripción identifica correctamente cuándo y dónde puede usarse esta alternativa?","why":"La alternativa es condicional, no la opción preferida por defecto. Úsala en las configuraciones de corredores indicadas cuando dé una visión sin obstáculos de home y del bateador. Comprueba la línea de visión con bateadores zurdos y diestros, incluido el efecto de la trayectoria de salida del lanzador. El árbitro debe seguir pudiendo ajustarse hacia la 2BDA, llegar al borde de entrada o entrar para cubrir primera si U1 sale. No debe desplazarse más hacia la prolongación de la línea de primera."},{"options":["Porque puede dejar la base entre el árbitro y la jugada, aumentando el paralaje y ocultando el contacto del corredor con la base. El movimiento debe conservar el acceso hacia la 2BDA y el lado de 1B en el borde de entrada.","Porque aleja al árbitro de un ángulo de 90 grados respecto al tiro del receptor, que debe seguir siendo la alineación principal durante todo el intento de tag.","Porque aumenta la distancia al punto del tag, así que el árbitro debe moverse directamente hacia la base en lugar de ajustar el ángulo de visión a medida que se desarrolla la jugada.","Porque saca al árbitro de la zona inicial estándar, que debe mantenerse hasta completar el tag antes de ajustarse para una jugada secundaria."],"q":"Desde la posición alternativa del lado de tercera en segunda, ¿por qué debe evitar el árbitro desplazarse más a la derecha, hacia la prolongación de la línea que va de primera a segunda?","why":"La alternativa ya sitúa al árbitro en el lado de tercera de la 2BDA. Desplazarse más hacia la 1BLE puede dejar la base entre el árbitro y el tag, reduciendo la separación visual y distorsionando si el corredor sigue en contacto con la base. Lee la jugada y muévete primero hacia la 2BDA, y después ajústate hacia el lado de primera o hacia el borde de entrada según haga falta. La prioridad es una visión sin obstáculos de los elementos, no un ángulo fijo respecto al tiro ni permanecer dentro de una zona inicial."},{"options":["Moverse a la izquierda automáticamente sin leer el movimiento del receptor al recuperar la pelota y quedarse quieto.","Quedarse justo detrás del receptor durante la recuperación y el intento de tag.","Colocarse de inmediato en la prolongación de la línea de tercera en todas las jugadas.","Leer los hombros del receptor, despejar para permitir la recuperación, localizar la pelota, evitar la línea de tiro y establecer una posición de observación y de decisión que conserve los cuatro elementos; el despeje puede ser a la izquierda o a la derecha."],"q":"En un passed ball o un wild pitch, el árbitro de home no tiene que rotar hacia tercera y un corredor avanza hacia home. ¿Qué movimiento sigue el Apéndice 5a?","why":"El movimiento inicial habitual a la izquierda tiene excepciones. En un passed ball o un wild pitch sin rotación ni cobertura obligatorias en tercera, despeja según el giro del receptor y luego lee la jugada en home y ajústate. Evita la 3BLE cuando deje el plato entre tú y el corredor."},{"options":["Repasar la cuenta, los outs, la posición de los corredores y la cobertura asignada, y aplicar los patrones de rotación estándar sin adaptar la preparación a la velocidad, el alcance o el brazo de cada jugador.","Combinar la cuenta, los outs y el marcador con la velocidad y las posibilidades de avance de los corredores, la profundidad y el brazo de los jardineros y la capacidad de los fildeadores, para anticipar las jugadas probables sin dejar de estar preparado para adaptarse.","Identificar la jugada más probable a partir de la alineación defensiva y comprometerse con su posición de decisión antes del contacto, para llegar antes que el corredor y el tiro.","Dar prioridad a la velocidad del corredor adelantado y a la posición del fildeador más cercano, dejando para cuando se batee la pelota la valoración de los demás corredores, la profundidad del outfield y las posibles jugadas secundarias."],"q":"¿Qué enfoque describe mejor la información que el árbitro debe tener en cuenta en la Preparación Previa al Lanzamiento (PPP) según el Apéndice 5a?","why":"La PPP combina la colocación inicial correcta con el conocimiento de la situación del partido y de las capacidades de los jugadores. Ten en cuenta la cuenta, los outs, el marcador, la velocidad y las intenciones de los corredores, la colocación y el brazo de los jardineros, y el alcance de los fildeadores y su capacidad para ejecutar una jugada. Usa esa información para anticipar posibilidades y adaptarte con rapidez. Anticipar una jugada no significa comprometerse con su resultado ni moverse antes de tiempo a una posición de decisión predeterminada."},{"options":["Usar las posiciones iniciales de los jardineros para elegir la cobertura en el momento del contacto, y luego confirmar la trayectoria de la pelota y comunicarlo una vez que se mueve hacia el outfield.","Leer la dirección inicial de la pelota y comprometerse si entra en su zona de cobertura, dejando que los compañeros se ajusten al ver su movimiento.","Leer la trayectoria y las reacciones de los jardineros, pero dar la primera opción al árbitro de 2B, porque su posición central ofrece la cobertura más amplia.","Leer la trayectoria de la pelota y la posibilidad de atrapada, comprobar los movimientos y las prioridades de cobertura de los compañeros y comunicar antes de comprometerse a salir."],"q":"Según el Apéndice 5a, ¿qué debe hacer un árbitro de base antes de decidir salir a un fly?","why":"Observa la trayectoria real antes de comprometerte. Conocer antes del lanzamiento la profundidad y la capacidad de los jardineros ayuda a decidir, pero no sustituye leer la pelota. Comprueba a tus compañeros y comunícate. El árbitro de esquina tiene la primera opción sobre el árbitro de segunda; con las dos esquinas ocupadas en el ejemplo de tres árbitros, U1 tiene la primera opción. Sal cuando la jugada lo exija dentro de la cobertura asignada, evitando movimientos innecesarios que debiliten la cobertura de las bases o de home."},{"options":["Seguir hacia el outfield para confirmar cómo se fildea la pelota, dejando que los demás árbitros amplíen su cobertura de bases hasta que vuelva la pelota.","Moverte hacia el jardinero para tener un mejor ángulo sobre el tiro de vuelta y volver luego hacia las bases cuando la defensa elija su jugada.","Mantener la cobertura de bases necesaria, seguir conectado visualmente con la pelota y los corredores y evitar una salida innecesaria.","Seguir la pelota más allá de las bases hasta que el jardinero la controle y decidir después qué base necesita cobertura según la dirección del tiro."],"q":"Un batazo normal ha caído claramente y bota por el outfield, sin que ninguna decisión de atrapada, fair/foul o home run te obligue a salir. Varios corredores avanzan. ¿Qué debes hacer?","why":"Una vez que la pelota ha caído claramente y ninguna decisión del outfield exige salir, mantén la cobertura de bases asignada y prepárate para los corredores que avanzan y las jugadas secundarias. Mantén a la vista la pelota y los corredores, lee el tiro que se va formando y ajústate para tener el ángulo y la distancia necesarios. Salir sin necesidad puede debilitar la cobertura, sobre todo en tercera y en home."},{"options":["Volver para cubrir ese lugar vacío si hace falta y comunicar con claridad la responsabilidad al equipo arbitral, o aportar lo que observó si el árbitro responsable le pide información.","Volver automáticamente y hacerse cargo de la base que no cubre otro árbitro.","Tomar una decisión en el infield sin decir al equipo arbitral que la cobertura ha cambiado.","Ignorar la jugada sin cubrir, porque al haber salido el árbitro terminan todas sus funciones de árbitro de base."],"q":"Tras completar su decisión en el outfield, el árbitro que salió mira hacia atrás y ve que una base cercana ha quedado sin cubrir por una rotación fallida, con una jugada a punto de producirse. ¿Qué puede hacer ese árbitro según el Apéndice 5a?","why":"Se trata de una corrección de élite concreta para una cobertura que falta, no de volver por rutina a una zona ya ocupada. El árbitro que sale debe mirar hacia atrás y observar las jugadas del infield. Una comunicación clara como «Estoy aquí» y el nombre del árbitro indica a los compañeros que el lugar vacío está cubierto."},{"options":["Que el lanzador tenga la pelota bien sujeta en el círculo y todos los corredores vuelvan a sus bases, lo que permite que cada árbitro empiece a moverse por su cuenta.","Que U1, en home, pida tiempo, seguido de una contrarrotación coordinada en la que el árbitro que llega asume el control antes de que el que sale deje la zona.","Que U2 o U3 empiece a volver hacia su posición inicial, lo que lleva a U1 y al árbitro de home a seguirle cuando reconocen el movimiento.","Que el árbitro de home inicie la vuelta hacia home y los árbitros de base se ajusten a medida que ese movimiento deja espacio para la contrarrotación."],"q":"Han terminado todas las jugadas y U1 está en home. ¿Qué da paso a que el equipo arbitral contrarrote hacia las posiciones del siguiente lanzamiento?","why":"Cuando han terminado todas las jugadas y U1 está en home, U1 pide tiempo para que el equipo arbitral contrarrote. La vuelta es coordinada: un árbitro mantiene su responsabilidad hasta que el árbitro que llega asume el control. La posesión de la pelota en el círculo del lanzador no inicia por sí sola esta secuencia, y marcharse antes de tiempo puede dejar una base sin cubrir."}],"title":"Apéndice 5a: Conceptos clave","nextLabel":"Continúa con la presentación - Apéndice 5b: Sistema de tres árbitros"},"m07-mkc":{"questions":[{"options":["Unos 3,5 metros detrás de tercera, hasta 2 metros fuera de la línea en territorio foul.","Unos 5,5 metros detrás de tercera, justo fuera de la línea en territorio foul.","Unos 4,5 metros detrás de tercera, justo fuera de la línea en territorio foul.","Unos 3,5 metros atrás cerca de la 2BDA, en el lado de primera de segunda."],"q":"Sin corredores en base, ¿qué posición inicial de U3 sigue el Apéndice 5b?","why":"La referencia sin corredores es unos 5,5 metros detrás de tercera, justo fuera de la línea. Las demás distancias y ubicaciones corresponden a otras configuraciones de corredores. La profundidad es aproximada y debe permitir moverse a tiempo y tener una visión clara."},{"options":["Retroceder unos 3 metros desde la posición inicial antes de leer el tag.","Mantener la posición inicial todo el tiempo, porque la 2BDA es el punto final de decisión.","Ajustarse a una posición a unos 3 metros de la base, manteniendo a la vista los Cuatro Elementos Esenciales mientras se desarrolla el tag.","Colocarse en la prolongación de la línea de primera antes de que llegue el tiro para prepararse para cualquier tag de barrido."],"q":"U3 empieza cerca de la 2BDA y lee un pickoff en segunda. ¿Qué descripción sigue la indicación sobre pickoffs?","why":"Unos 3 metros describe la distancia de trabajo respecto a la base, no un retroceso obligatorio de tres metros. Lee al corredor y al fildeador y ajústate para tener una visión sin obstáculos. El encabezado del PDF se refiere a U3, aunque la frase que sigue dice U2 por error."},{"options":["U1 se encarga de primera, U3 de segunda y el árbitro de home de tercera.","El árbitro más cercano a cada corredor se encarga de ese corredor, sea cual sea la posición asignada.","U1 se encarga de primera y segunda; U3, de tercera.","U1 se encarga de primera, y el árbitro de home de segunda y tercera mientras U3 lee el outfield."],"q":"En un sistema de tres árbitros con corredores en 1B y 3B, ¿qué reparto de la responsabilidad sobre los despegues sigue el Apéndice 5b?","why":"El reparto de los despegues es U1 en primera y segunda y U3 en tercera. No confundas salir antes de tiempo en el lanzamiento con las responsabilidades de tag-up en un fly atrapado."},{"options":["U1 tiene un buen ángulo sobre la línea del jardín derecho y las pelotas atrapadas a ras de suelo que van hacia la línea, mientras que U3 puede entrar más fácilmente para cubrir las bases y el tag-up sin que U1 tenga que hacer el button-hook cruzando la trayectoria del corredor.","U3 debe quedarse fuera en segunda durante toda la jugada, así que U1 toma la pelota sobre todo para no cambiar el ángulo de visión inicial de U3.","Que U1 salga quita al equipo arbitral todas las responsabilidades en primera hasta que la pelota vuelve al infield.","La ruta más profunda de U1 le da prioridad sobre U3 en cualquier pelota al outfield."],"q":"En un sistema de tres árbitros con un corredor en primera, U1 en primera y U3 en segunda, ¿por qué se asigna a U1 la zona del jardín derecho, incluidas algunas pelotas justo detrás de U3?","why":"El reparto combina buenos ángulos sobre la línea y las pelotas atrapadas a ras de suelo con una cobertura eficaz de las bases. U3 puede entrar en el diamante, vigilar el tag-up y cubrir primera y segunda con más facilidad de lo que U1 puede hacer a tiempo un button-hook alrededor del corredor."},{"options":["El árbitro de home lleva al bateador-corredor hasta tercera mientras el árbitro de base que queda se encarga de 1B y 2B.","El árbitro de base que queda lleva al bateador-corredor hasta tercera y lo comunica para que el árbitro de home pueda cubrir home.","El árbitro del outfield vuelve a tercera después de decidir sobre la atrapada mientras el árbitro de base que queda se mantiene en segunda.","El árbitro de base que queda deja de cubrir en segunda y transfiere todas las jugadas en tercera al árbitro de home."],"q":"Un árbitro de base sale y el fly no es atrapado. ¿Quién lleva al bateador-corredor hasta tercera en el sistema de tres árbitros de élite?","why":"El árbitro de base que queda cubre primera y segunda y lleva al bateador-corredor hasta tercera. En un fly atrapado, llevar al último corredor a tercera depende de llegar a una posición ventajosa y de comunicarse con el árbitro de home."}],"title":"Apéndice 5b: Sistema de Tres Árbitros","nextLabel":"Continúa con la presentación - Apéndice 5b: Sistema de Tres Árbitros"},"m08-mkc":{"questions":[{"options":["Detrás del receptor, para ver los cajones de bateo","Junto a los dugouts, para hablar con los managers","Delante de los cajones de bateo, para poder dispersarse hacia sus posiciones iniciales","En sus posiciones iniciales, para que nadie tenga que moverse"],"q":"En la reunión previa al partido en el plato en el Sistema de Cuatro Árbitros, ¿dónde se alinean U2, U1 y U3, y por qué?"},{"options":["A un tercio del camino de HP a 1B","A dos tercios del camino de HP a 1B","A mitad de camino de HP a 1B","Detrás de 1B"],"q":"Entre entradas en el Sistema de Cuatro Árbitros, ¿dónde se coloca U1?"},{"options":["A unos 5,5 m (18 pies) detrás de 1B","A unos 3,5 m (12 pies) detrás de 1B en territorio de foul","A unos 4,5 m (15 pies) detrás de 1B en territorio fair","Sobre la línea de 1B, a la altura de la base"],"q":"En el Sistema de Cuatro Árbitros, ¿dónde se coloca U1 al inicio con un corredor en 1B?"},{"options":["U1","U3","U2","PU"],"q":"En el Sistema de Cuatro Árbitros, U2 sale a un fly. ¿Quién se encarga del tag-up en 3B?"},{"options":["PU","U1 o U3, por indicación de U2","U2 siempre tiene la primera opción","Al árbitro más cercano a la pelota"],"q":"En un fly que puede tomar un árbitro de base o U2, ¿a quién se da la primera opción de salir en el Sistema de Cuatro Árbitros?"},{"options":["Se queda en home","Se mueve a 3B para cubrir la jugada","Sigue al bateador-corredor aproximadamente un tercio del camino hacia 1B, vigilando la interferencia y la decisión de fair/foul","Rota hacia dentro para cubrir 2B"],"q":"En el Sistema de Cuatro Árbitros sin corredores o con un corredor en 1B, ¿qué hace PU en una jugada con la pelota viva desde el infield?"},{"options":["Solo de las decisiones de fair/foul en las líneas","De las jugadas en 1B y 3B","De los tag-ups en todas las bases","De todas las decisiones más allá del árbitro de base y detrás de los jugadores de cuadro (fair/foul, atrapada o no, y el estado de una pelota que sale del campo), sin importar los corredores"],"q":"En los Sistemas de Cinco y Seis Árbitros, ¿de qué son responsables ULF y URF?"},{"options":["Delante del jardinero, para juzgar con precisión las bolas atrapadas a ras de suelo","Detrás del jardinero","En el poste de foul","En la posición inicial del árbitro de base"],"q":"En los Sistemas de Cinco y Seis Árbitros, si LF o RF juega cerca, ¿dónde debe estar el árbitro de outfield?"}],"title":"Apéndice 5c y d: Sistemas de Cuatro, Cinco y Seis Árbitros","nextLabel":"Continúa con la presentación - Apéndice 5c y d: Sistemas de Cuatro, Cinco y Seis Árbitros"},"m07-pca":{"questions":[{"options":["PU a un tercio hacia tercera; U1 a mitad de camino hacia primera; U3 a dos tercios hacia tercera.","PU a mitad de camino hacia tercera; U1 a un tercio hacia primera; U3 a dos tercios hacia tercera.","PU a un tercio hacia tercera; U1 a dos tercios hacia primera; U3 a mitad de camino hacia tercera.","PU a un tercio hacia primera; U1 a mitad de camino hacia primera; U3 a dos tercios hacia tercera."],"q":"¿Qué colocación completa entre entradas sigue el Apéndice 5b, con todos los árbitros fuera de las líneas de fair/foul?","why":"La colocación indicada es PU a un tercio en el lado de tercera, U1 a mitad de camino en el lado de primera y U3 a dos tercios en el lado de tercera, todos fuera de las líneas."},{"options":["Unos 3,5 metros detrás de primera y a 2-3 metros de la línea en territorio foul, con la misma separación lateral que U3 con un corredor en tercera.","Unos 5,5 metros detrás de primera, justo fuera de la línea en territorio foul.","Unos 3,5 metros detrás de primera en territorio foul, cerca de la línea, con visión sin obstáculos de home y preparado para un tiro de vuelta.","Unos 3,5 metros atrás en el lado de tercera de la 2BDA, usando la colocación alternativa de segunda."],"q":"Con un corredor solo en primera, ¿qué posición inicial de U1 sigue el Apéndice 5b?","why":"U1 empieza unos 3,5 metros detrás de primera en territorio foul. La posición junto a la línea facilita un tiro de vuelta rápido y la cobertura de fair/foul. U1 puede ajustarse ligeramente para ver bien home; la separación más amplia de U3 en tercera no se copia automáticamente en primera."},{"options":["Para alinearse directamente con el tiro del receptor y mantener esa alineación fija en cualquier pickoff, aunque el tag se desplace.","Para tener una ruta más temprana hacia segunda y soltar tercera antes de que el corredor se comprometa hacia home.","Para tener una única posición de decisión cercana que sirva para cualquier tag posible sin más ajustes.","Para mantener la visión del lanzador, el corredor, el bateador y home incluso cuando el corredor despega hacia territorio foul y taparía una posición junto a la línea."],"q":"¿Por qué puede U3 empezar unos 3,5 metros detrás de tercera y hasta 2 metros fuera de la línea en territorio foul cuando hay un corredor en tercera?","why":"La separación protege la visión de U3 durante el lanzamiento y el despegue, sobre todo cuando un corredor despega muy abierto en territorio foul. U3 lee el regreso del corredor y el tag del fildeador y se ajusta en lugar de mantener un punto fijo de decisión."},{"options":["Mantener la distancia de unos cinco metros de la jugada forzada y quedarse a 90 grados del tiro aunque el fildeador intente un tag de barrido.","Empezar justo fuera de la línea de fair/foul y trabajar hasta unos 3 metros en territorio foul sin pasar de una línea de 45 grados que atraviesa primera, o entrar en territorio fair cuando la jugada en el borde de entrada exige esa visión.","Ir a la prolongación de la línea de primera antes de leer el regreso del corredor, usando la misma posición en todos los tiros de vuelta.","Colocarse justo al lado del guante del fildeador y usar la llegada de la pelota para determinar si el corredor está out."],"q":"Desde primera, U1 lee un tiro de pickoff de vuelta a la base. ¿Qué colocación sigue el Apéndice 5b?","why":"Lee la trayectoria del corredor y la acción del fildeador. La guía permite un ángulo en territorio foul dentro del límite indicado o entrar un paso para ver el borde de entrada. El objetivo es ver a la vez el tag y el contacto con la base."},{"options":["Solo las afirmaciones 1 y 2.","Solo las afirmaciones 1, 3 y 4.","Solo las afirmaciones 2, 3 y 4.","Las cuatro afirmaciones."],"q":"Un árbitro de base sale a un fly al outfield. ¿Qué afirmaciones describen correctamente la cobertura de los tag-ups?","statements":["El árbitro de base que queda es responsable de los tag-ups en primera y segunda.","PU es responsable del tag-up en tercera.","El árbitro de base que queda debe rotar hacia dentro rápidamente y mirar por encima del hombro cuando haga falta para observar el primer toque y al corredor.","Si no se vio la relación necesaria, el equipo arbitral debe pedir ayuda e identificar con claridad al árbitro que hizo la observación pertinente."],"why":"Las cuatro son correctas. La cobertura interior restante se reparte para que el árbitro de base vigile los tag-ups de primera y segunda y PU el de tercera. Si una rotación impide ver a la vez el primer toque y al corredor, usa la información del compañero y comunica quién hizo la observación; no la deduzcas."},{"options":["U1, porque el reparto de los despegues asigna primera y segunda a U1 y tercera a U3.","U3, porque la excepción aparte del tag-up en segunda también le transfiere todos los despegues allí.","PU, porque el árbitro de home es quien ve más directamente la suelta del lanzamiento.","U1 y U3 conjuntamente, y decide el que señale primero."],"q":"Hay un corredor en segunda y U3 está en tercera. ¿Qué árbitro decide sobre el despegue cuando se realiza el lanzamiento?","why":"U1 tiene la responsabilidad del despegue en segunda. Un despegue en el lanzamiento y un tag-up en un fly atrapado son observaciones distintas con repartos distintos; la excepción del tag-up no cambia esta asignación del despegue."},{"options":["U3 toma la atrapada porque el jardinero central empezó dentro del sector central normal de U3, mientras U1 se queda en primera.","U1 toma el fly hacia la derecha; U3 entra en el diamante, lee el movimiento y prepara la cobertura del resto de bases.","PU toma la atrapada siempre que el jardinero central se desplace, y los dos árbitros de base mantienen sus bases iniciales.","U1 y U3 salen los dos hasta que se vea por qué lado del centro se hará la atrapada."],"q":"Sin corredores, con U1 en primera y U3 en tercera, un fly lleva al jardinero central, en su posición normal, hacia el jardín derecho. ¿Qué cobertura es correcta?","why":"Desde las esquinas, U1 cubre al jardinero central en posición normal que se desplaza hacia la derecha y el sector de foul del jardín derecho. U3 cubre el centro hacia la izquierda. Lee la trayectoria y a los compañeros y comunícate antes de comprometerte."},{"options":["U3 toma las dos decisiones porque U3 es el árbitro asignado al lado de tercera.","U1 toma las dos decisiones cruzando la zona de cobertura central y deja a U3 la cobertura de primera.","PU toma las dos decisiones en el sector abierto de la línea del jardín izquierdo mientras los árbitros de base mantienen la rotación necesaria.","U3 toma la atrapada desde segunda mientras PU toma por separado el fair/foul, sin traspaso de cobertura."],"q":"Con un corredor en primera, U1 en primera y U3 en segunda, un fly lleva al jardinero izquierdo hacia la línea de foul del jardín izquierdo. ¿Quién toma las decisiones de fair/foul y de atrapada?","why":"Con U3 empezando en segunda, PU cubre al jardinero izquierdo que va hacia la línea de foul abierta del jardín izquierdo. U3 cubre el sector central y al jardinero izquierdo que va hacia el centro. Especificar la dirección del fildeador evita la ambigüedad de decir solo «a F7»."},{"options":["U3 toma la jugada inicial en primera mientras PU se queda en home todo el tiempo.","PU entra en el diamante, toma la posible jugada inicial en primera y luego suelta primera a U3 cuando el bateador-corredor pasa primera; U3 cubre el resto del avance y PU se prepara para cubrir tercera o home.","U1 vuelve del outfield para la jugada en primera y sale de nuevo si la pelota sigue fuera.","PU sigue al bateador-corredor por primera, segunda y tercera mientras U3 se encarga de home."],"q":"Sin corredores, U1 sale hacia la derecha y se produce una posible jugada sobre el bateador-corredor en primera. ¿Qué cobertura inicial y qué traspaso siguen el Apéndice 5b?","why":"El caso sin corredores con U1 fuera es una excepción a un reparto general de primera y segunda. PU se encarga de la posible jugada inicial en primera. U3 rota hacia dentro y asume primera y segunda cuando el bateador-corredor pasa primera, y después lleva al bateador-corredor hacia tercera mientras PU se prepara para home."},{"options":["Quedarse en el POP y dejar a U1 la interferencia, un posible tag antes de primera y el fair/foul.","Rotar de inmediato a tercera y transferir a U3 todas las observaciones de la zona de primera antes del tiro.","Seguir al bateador-corredor hasta primera y continuar hacia segunda aunque U3 haya rotado allí.","Seguir aproximadamente un tercio del camino hacia primera, más si hace falta, conservar la decisión de fair/foul y las funciones de ayuda, y rotar hacia tercera si el bateador-corredor avanza hacia segunda."],"q":"Sin corredores y con un rodado al infield, ¿qué enfoque combina correctamente las funciones de seguimiento y de cobertura de PU?","why":"PU sigue al bateador-corredor por una posible interferencia, un tag más cerca de home y para ayudar en primera, conservando la responsabilidad de fair/foul. Cuando el bateador-corredor llega a primera y avanza hacia segunda, PU se prepara para cubrir tercera en lugar de duplicar a U3 en segunda."},{"options":["Solo las afirmaciones 1, 2 y 4.","Solo las afirmaciones 1 y 3.","Solo las afirmaciones 2 y 3.","Las cuatro afirmaciones."],"q":"PU o U1 cubre home desde la zona de observación POP. ¿Qué afirmaciones siguen la presentación del Apéndice 5b?","statements":["Si el receptor ya tiene la pelota y la jugada es en el borde de entrada, moverse hacia delante y a la izquierda según haga falta para conservar la visión.","Si la pelota y el corredor llegan a la vez y se desarrolla un tag de barrido más profundo o por fuera, ajustarse hacia delante y a la derecha según haga falta para ver el tag.","Moverse hacia la prolongación de la línea de tercera antes de que se desarrolle el tag, comprometiéndose pronto con una posición de tag de barrido en lugar de conservar el acceso al borde de entrada.","Usar la trayectoria del corredor, el momento de la pelota y la posible obstrucción o interferencia para leer la jugada, manteniendo los elementos a la vista mientras cambia."],"why":"Las afirmaciones 1, 2 y 4 son correctas. La posesión del receptor, la llegada del corredor y la llegada de la pelota ayudan a identificar la zona probable de contacto. Lee la jugada y ajústate desde el POP, conservando la visión y la capacidad de reaccionar a un cambio. Una posición poco habitual de tag de barrido no es el destino rutinario."},{"options":["Moverse a la derecha hacia la 2BDA como respuesta rutinaria a cualquier jugada en segunda, aplicando a la jugada forzada el movimiento del tag en un robo y manteniendo la diagonal como referencia final de decisión.","Acercarse siguiendo la alineación inicial sin cambiar el ángulo lateral, usando la cercanía para juzgar la posesión y el contacto con la base aunque el fildeador tape la llegada del corredor.","Leer el tiro y moverse a la izquierda hacia el borde de entrada, buscando unos 90 grados respecto al tiro y no más de 45 grados respecto al borde de entrada, con los cuatro elementos a la vista.","Moverse a la derecha hacia la prolongación de la línea de primera a segunda para centrar la base en la visión y mantener esa alineación para decidir el forzado antes de plantearse otro ángulo para un tag posterior."],"q":"Con un corredor en primera, U3 empieza en el lado de primera de la 2BDA, más cerca de segunda. Un tiro del infield da lugar a una jugada forzada en segunda. ¿Qué ajuste sigue la mecánica de élite?","why":"Estar más cerca de segunda no corrige un mal ángulo. Desde la posición estándar en el lado de primera, lee la jugada forzada y trabaja hacia tu izquierda, hacia el borde de entrada. No te muevas automáticamente a la derecha en una jugada forzada. Un ajuste hacia la 2BDA puede servir para un tag en un robo, pero esa es otra jugada. Mantén a la vista la posesión, el contacto del fildeador con la base y al corredor, y vuelve a ajustarte si se desarrolla un tag."},{"options":["Usar por defecto la alternativa del lado de tercera, porque un posible robo tiene siempre prioridad sobre la visión de todo el lanzamiento y el acceso a primera.","Usar la posición estándar preferida del lado de primera, cerca de la 2BDA hacia la 3BLE, unos 3,5 metros atrás, o la alternativa condicional del lado de tercera con home sin obstáculos; cuando haga falta ajustarse desde la alternativa, moverse primero hacia la 2BDA y conservar el acceso al interior y al borde de entrada.","Empezar hacia la prolongación de la línea de primera para tener una visión de tag de barrido antes de leer si el corredor intenta robar o se pasa de la base.","Empezar más atrás, fuera del alcance de los fildeadores, para que el lanzador no tape al bateador, aceptando una ruta más larga hacia dentro si U1 sale."],"q":"Con un corredor solo en primera, U3 elige una posición inicial en segunda teniendo en cuenta si el bateador es diestro o zurdo, el movimiento del lanzador y la posible cobertura de primera si U1 sale. ¿Qué enfoque es correcto?","why":"La presentación señala como preferida la posición del lado de primera porque conserva la ruta más corta hacia dentro, incluida la cobertura de primera. La alternativa es condicional, cerca de la 2BDA, y debe conservar la visión durante todo el lanzamiento. Desde la alternativa, el movimiento inicial es hacia la 2BDA, no más hacia la 1BLE."},{"options":["U3 vigila el tag-up en segunda, U1 vigila primera y PU juzga el fly, comunicando la ayuda si una observación necesaria queda bloqueada.","U1 debe vigilar los dos tag-ups porque U1 tiene las decisiones de despegue en primera y segunda.","PU debe vigilar los dos tag-ups además de la atrapada porque ningún árbitro de base salió.","U3 vigila primera y U1 vigila segunda, sean cuales sean sus líneas de visión reales durante la rotación."],"q":"Hay corredores en primera y segunda, nadie en tercera, y ningún árbitro de base sale. PU tiene un fly al sector abierto de la línea del jardín derecho. ¿Qué reparto de los tag-ups sigue la excepción indicada?","why":"Con primera y segunda ocupadas y tercera vacía, U3 tiene el tag-up de segunda. La presentación explica que U3 puede ver esa relación mientras U1 rota hacia dentro y tiene que vigilar primera. La responsabilidad del despegue en el lanzamiento es un reparto aparte."},{"options":["Rotar hacia dentro en cuanto se fildea la pelota, dejando a PU cualquier regreso inmediato a tercera.","Quedarse en tercera hasta que terminen todas las posibles jugadas en primera y segunda, incluso después de que el corredor se comprometa hacia home.","Mantener 3B hasta que el corredor se comprometa hacia home y luego rotar a segunda; si U3 se queda o se retrasa, U1 debe cubrir primera y segunda.","Seguir al corredor hasta home y obligar a PU a rotar por tercera hacia segunda."],"q":"Con un corredor solo en tercera, U1 en primera y U3 en tercera, se desarrolla un rodado al infield. ¿Qué debe hacer U3?","why":"No abandones a un corredor sobre el que todavía puede haber jugada en tercera. Cuando el corredor se compromete hacia home, U3 puede soltar y rotar. U1 lee el movimiento de U3 y cubre primera y segunda si U3 no puede soltar."},{"options":["Rotar al POP de inmediato en el contacto y dejar a PU la posible jugada forzada inicial en primera.","Hacer el button-hook hacia segunda y mantener toda la cobertura de home con PU hasta que el bateador-corredor se detenga en tercera.","Quedarse detrás de primera todo el tiempo, obligando a PU a cubrir al bateador-corredor en tercera y en home si el avance continúa.","Prepararse para una jugada forzada del outfield a primera y observar primera, y luego rotar al POP si el bateador-corredor avanza de segunda hacia tercera, comunicándolo para empujar a PU hacia tercera."],"q":"Sin corredores y con los dos árbitros de base en las esquinas, un rodado llega al outfield. ¿Qué secuencia de U1 sigue el Apéndice 5b?","why":"Sin corredores originales, U1 protege primero la posible jugada del outfield a primera. En este caso, el avance del bateador-corredor de segunda hacia tercera activa la rotación de U1 a home. No apliques este momento a un caso con corredor en primera, en el que el corredor adelantado puede amenazar home antes."},{"options":["U3 vuelve a tercera sin decir nada mientras U1 sigue cubriendo segunda, tercera y home hasta el siguiente lanzamiento.","U3 toma segunda sin comunicarlo, suponiendo que U1 se dará cuenta y cambiará la rotación antes de que llegue el corredor.","U3 sigue saliendo solo para mantener la señal original de salida, aunque el equipo arbitral pueda recuperar con seguridad una mejor cobertura del infield.","U3 comunica con claridad, con la vista y con la voz, que tiene segunda y rota hacia dentro; U1 ajusta el button-hook y puede seguir hacia home, coordinando la cobertura de tercera de PU."],"q":"Con U1 en primera y U3 en tercera, U3 empieza a salir pero lee que la pelota no será atrapada. U1 ya ha iniciado la respuesta hacia dentro. ¿Qué corrección sigue la presentación del Apéndice 5b?","why":"La corrección recupera la rotación del infield de tres árbitros y mejora la cobertura alrededor del diamante. La comunicación es esencial porque U1 puede haber reaccionado ya al movimiento inicial de U3. Lee la jugada y coordínate en lugar de invertir la cobertura sin decir nada."},{"options":["Reproducir desde dentro la posición exterior de la 2BDA y mantener el mismo ángulo aunque el corredor se aleje y el fildeador tape el tag.","Leer la jugada y elegir un carril de trabajo interior: hacia la línea de tercera para una jugada en el borde de entrada, o hacia la línea de primera para ver de vuelta un tag que se desarrolla fuera de la base.","Acercarse a la base en línea recta en todos los tags, confiando en la distancia para compensar un ángulo bloqueado a un lado de la base.","Elegir el carril según el tiro previsto antes de que llegue el corredor y mantenerlo durante el tag, dejando cualquier otro ajuste para la siguiente jugada."],"q":"Después de que U3 sale, U1 trabaja por dentro para primera y segunda. En segunda, ¿qué forma de moverse sigue la presentación cuando cambia el lugar del tag?","why":"La colocación interior tiene restricciones distintas de las de una posición inicial exterior. Lee el lugar probable del tag y usa el carril que lo mantenga delante, y adáptate si cambia. Son carriles de trabajo interiores, no un permiso para desplazarse más hacia la 1BLE desde la alternativa exterior del lado de tercera. Protege la separación de los elementos y evita simplemente reproducir la mecánica exterior."},{"options":["Quedarse a la profundidad inicial en todos los tiros de vuelta y usar la línea de tiro del receptor como ángulo fijo de decisión.","Ir de inmediato a territorio fair, al borde de entrada, en todos los tiros de vuelta, aunque el corredor vuelva por territorio foul.","Leer el regreso del corredor y el tag del fildeador, trabajar a unos 3 metros de tercera en territorio foul y ajustarse para tener la visión necesaria del tag o del borde de entrada.","Colocarse detrás del corredor que vuelve para alinear al corredor, el guante y la base, usando la cercanía para saber si el tag llegó primero."],"q":"¿Qué forma de actuar de U3 sigue la indicación sobre pickoffs en tercera base?","why":"La trayectoria de regreso del corredor y la acción del fildeador marcan el ángulo. La referencia en territorio foul es de unos 3 metros con el límite de 45 grados. Ajústate para ver el tag real; no supongas que todos los regresos usan el mismo punto de contacto."},{"options":["Rotar hacia dentro, pasando la línea de la placa del lanzador a segunda, asumir la cobertura de primera y segunda y estar preparado para llevar al bateador-corredor hacia tercera con una comunicación clara.","Quedarse fuera cerca de la 2BDA y cubrir primera y segunda desde allí para que PU se encargue de todas las jugadas en tercera.","Ir a la zona de espera de tercera y transferir primera y segunda a PU hasta que la pelota del outfield haya vuelto.","Mantener el borde de entrada de tercera para el siguiente tiro y dejar primera sin cubrir hasta que U1 vuelva del outfield."],"q":"U1 ha salido a un fly. ¿Qué respuesta de U3 sigue el Mapa de Memoria de Rotación de Tres Árbitros?","why":"El mapa de memoria sitúa a U3 por dentro, pasada la línea del lanzador a segunda, para primera y segunda cuando U1 sale. Lee al corredor y comunica la cobertura continuada de tercera. Sin corredores originales, el caso detallado con U1 fuera da a PU la jugada inicial en primera antes de que U3 la asuma cuando el bateador-corredor pasa primera."}],"title":"Apéndice 5b: Sistema de tres árbitros","nextLabel":"Continúa con la presentación - Apéndice 5c y d: Sistemas de cuatro, cinco y seis árbitros"},"m08-pca":{"questions":[{"options":["A un tercio del camino de HP a 1B","Detrás de 2B","Junto a PU","A dos tercios del camino de HP a 1B"],"q":"En el Sistema de Cuatro Árbitros (Apéndice 5c), ¿dónde se coloca U2 entre entradas?","why":"Entre entradas, PU se coloca a un tercio del camino de HP a 3B, U1 a un tercio del camino de HP a 1B, U2 a dos tercios del camino de HP a 1B y U3 a dos tercios del camino de HP a 3B."},{"options":["A unos 3,5 m (12 pies)","A unos 4,5 m (15 pies)","A unos 5,5 m (18 pies)","A unos 2 m (6 pies)"],"q":"En el Sistema de Cuatro Árbitros, ¿a qué distancia aproximada detrás de 2B empieza U2 cuando hay un corredor en cualquier base?","why":"Sin corredor, la posición inicial del Ángulo Diagonal de Segunda Base está a unos 4,5 m (15 pies) atrás; con un corredor en cualquier base, a unos 3,5 m (12 pies)."},{"options":["U1","PU","U2","U3"],"q":"En el Sistema de Cuatro Árbitros, ¿quién sale a un fly al jardín central?","why":"U1 sale a los fly al jardín derecho y a F8 que corre hacia la derecha; U3, al jardín izquierdo y a F8 que corre hacia la izquierda. U2 debe dar a U1 o a U3 la primera opción."},{"options":["U2","PU","U3","Nadie"],"q":"En el Sistema de Cuatro Árbitros, U1 sale a un fly. ¿Quién se encarga del tag-up en 1B?","why":"PU se encarga del tag-up en 1B porque PU tiene los Cuatro Elementos Esenciales frente a él en todo momento. U2 se encarga de 2B y U3 de 3B."},{"options":["U1","PU","U3","U2, desde el outfield"],"q":"En el Sistema de Cuatro Árbitros, U2 sale a un fly. ¿Quién se encarga del tag-up en 2B?","why":"U1 conserva 1B, U3 se encarga de 2B, incluido el tag-up, y PU se encarga del tag-up en 3B."},{"options":["U1 siempre hace un button hook hacia el interior","U1 usa el territorio de foul de 1B o sale, y nunca necesita hacer un button hook","U1 se queda en 1B durante toda la jugada","U1 cubre 3B en cada fly"],"q":"¿Qué afirmación sobre U1 en el Sistema de Cuatro Árbitros es correcta, según el Mapa Mnemotécnico de Rotaciones?","why":"U1 también se comunica con PU cuando llega a HP y empuja a PU hacia 3B, y se aparta de HP cuando PU indica una situación de backfill."},{"options":["Quedarse fuera para tener un ángulo agudo sobre el tiro desde el jardín izquierdo para cualquier decisión en 2B","Hacer de inmediato un button hook hacia el interior para cualquier decisión en 2B","Moverse a la zona POP para ayudar a PU","Rotar a 3B"],"q":"Sistema de Cuatro Árbitros. Se batea un rodado al jardín izquierdo y ningún árbitro de base sale. ¿Qué debe hacer U2?","why":"En un batazo a RF o CF, U2 hace un button hook hacia el interior para cualquier decisión en 2B; en un batazo a LF, el ángulo agudo sobre el tiro es mejor desde fuera."},{"options":["Detrás de la cerca del outfield","En la línea de foul a la altura de 2B","Junto a PU, detrás de home","Delante del jardinero, a mitad de camino entre el jardinero y el árbitro de base, hasta un metro fuera de la línea en territorio fair"],"q":"En los Sistemas de Cinco y Seis Árbitros (Apéndice 5d), ¿dónde toman ULF y URF su posición inicial preliminar?","why":"Si LF o RF juega cerca, el árbitro de outfield debe estar siempre delante del jardinero para juzgar con precisión las bolas atrapadas a ras de suelo."},{"options":["PU toma todas las bolas fair/foul hasta la posición inicial de U1 o U3, y ULF y URF toman todas las demás decisiones","ULF y URF toman todas las decisiones de fair/foul","El árbitro de base más cercano toma todas las decisiones","PU no toma ninguna"],"q":"¿Cómo se reparte la responsabilidad de fair/foul en los Sistemas de Cinco y Seis Árbitros, según el Apéndice 5d?","why":"Al seguir una pelota cerca del poste de foul, el árbitro de outfield se mantiene bien atrás sobre la línea de foul para tener la profundidad adecuada y juzgar la trayectoria sobre el poste o la cerca."},{"options":["Siempre la toma el árbitro más lejano a la pelota","PU decide desde el plato","La decisión la toma el árbitro de base","Ambos corren hacia territorio fair en paralelo a la trayectoria de la pelota hasta tener un ángulo, y quien toma la decisión lo indica con una mano en el pecho o verbalmente"],"q":"En un fly al outfield en los Sistemas de Cinco y Seis Árbitros, ¿cómo deciden los árbitros de outfield quién toma la decisión?","why":"ULF y URF son responsables de todas las decisiones más allá del árbitro de base y detrás de los jugadores de cuadro: fair/foul, atrapada o no, y el estado de una pelota que sale del campo de juego."},{"options":["A unos 3,5 m (12 pies) detrás de 3B, en territorio de foul","A unos 4,5 m (15 pies) detrás de 3B, justo al lado de la línea en territorio de foul","A unos 3,5 m (12 pies) atrás, en el Ángulo Diagonal de Segunda Base","A unos 5,5 m (18 pies) detrás de 3B, justo al lado de la línea en territorio de foul"],"q":"En el Sistema de Cuatro Árbitros, ¿dónde empieza U3 con un corredor en 2B?","why":"Sin corredores, U3 empieza a unos 5,5 m (18 pies) detrás de 3B; con un corredor en 3B está a unos 3,5 m (12 pies) en territorio de foul."},{"options":["U1","PU","U2","U3, desde el jardín"],"q":"U3 sale a un fly en el Sistema de Cuatro Árbitros. ¿Quién se encarga del tag-up en 2B?","why":"Cuando U3 sale, U1 se encarga del tag-up en 1B y U2 del tag-up en 2B. Cada árbitro tiene el tag-up de su base después de la rotación inicial."},{"options":["Salir también al jardín","Ignorar el tag-up","Pedir ayuda a U3 con el tag-up en 2B","Pedir a PU que se encargue del tag-up en 2B"],"q":"U1 sale a un batazo fuerte y plano que es atrapado en el jardín derecho. Puede que U2 no llegue al interior a tiempo para ver la atrapada y el tag-up del corredor en 2B. ¿Qué puede hacer U2?","why":"Cuando los árbitros rotan hacia el interior con la Teoría Interior/Exterior, puede que no vean a la vez el primer contacto con la pelota y el despegue del corredor, así que rotan rápido, miran por encima del hombro y piden ayuda."},{"options":["PU, para todos los corredores","U2, para los corredores en 1B y 2B, y U1 para los demás","U1, para los corredores de todas las bases","Cada árbitro, para el corredor de su propia base"],"q":"En el Sistema de Cuatro Árbitros, ¿quién es responsable de decidir si un corredor sale antes de tiempo?","why":"En el Sistema de Tres Árbitros U1 tiene las salidas anticipadas en 1B y 2B; en el Sistema de Cuatro Árbitros cada árbitro tiene la de su base."},{"options":["Unos 90 grados respecto al tiro y no más de 45 grados respecto al borde de entrada","Directamente sobre la base","Justo en línea con el tiro","Detrás del fildeador, a 180 grados del tiro"],"q":"¿Qué ángulo deben buscar U2 y U3 en las jugadas forzadas en el Sistema de Cuatro Árbitros?","why":"En las jugadas de tag usan el movimiento dinámico para mantener a la vista los Cuatro Elementos Esenciales en el borde de entrada o donde lo exija la jugada."},{"options":["Correr al jardín con la pelota","Seguir el batazo y acompañar al bateador-corredor un tercio del camino hacia 1B, más lejos si hace falta","Rotar de inmediato a 3B","Quedarse en home en su posición"],"q":"En el Sistema de Cuatro Árbitros sin corredores o con un corredor solo en 1B, ¿qué hace PU en un batazo al jardín?","why":"Con un corredor en 2B o 3B, PU usa en cambio la posición de espera y anticipa las jugadas en el plato."},{"options":["Siempre que U3 sale","Cuando no hay corredores y el batazo va al jardín izquierdo","Siempre que el batazo va al cuadro interior","Cuando hay un corredor en 3B y el batazo va al jardín derecho"],"q":"Según el Mapa Mnemotécnico de Rotaciones del Sistema de Cuatro Árbitros, ¿en qué situación puede quedarse afuera U2?","why":"U2 debe rotar hacia el interior del cuadro en todas las demás situaciones en que U1 o U3 salen, y cubrir 1B cuando U1 sale."},{"options":["Salir al jardín en cada fly","Quedarse en sus posiciones iniciales durante toda la jugada","Dejar todas las decisiones a los dos árbitros de jardín","Quedarse en el cuadro interior y rotar como en el Sistema de Tres Árbitros, mientras dos árbitros de jardín situados en las líneas de fair/foul juzgan los fly, las bolas atrapadas a ras de suelo y los jonrones"],"q":"En el Sistema de Cinco Árbitros (Apéndice 5d), ¿qué hacen PU y los dos árbitros de base?","why":"Esto deja a los demás árbitros libres para atender las jugadas en las bases."},{"options":["Al círculo del lanzador","Detrás de home, al lado de PU","Por la línea hasta donde están las posiciones iniciales de U3 y U1","Detrás de la cerca del jardín"],"q":"Entre entradas en los Sistemas de Cinco y Seis Árbitros, ¿adónde van ULF y URF?","why":"Los demás árbitros usan las mismas posiciones entre entradas que en el Sistema de Tres o de Cuatro Árbitros."},{"options":["Permiten que los árbitros de base se queden en el cuadro interior, de modo que todas las bases estén cubiertas en todo momento y cada decisión se tome desde una posición ventajosa","Hacen que los partidos sean más cortos","Eliminan la necesidad de que PU esté en home","Eliminan la necesidad de decidir si la bola es fair o foul"],"q":"Según el Apéndice 5, ¿por qué son útiles los Sistemas de Cinco y Seis Árbitros?","why":"Las jugadas cercanas a home afectan el resultado general del partido, por lo que importa tener cubiertos 3B y home; los sistemas son adecuados para finales y partidos de alto nivel."}],"title":"Apéndice 5c y d: Sistemas de cuatro, cinco y seis árbitros","nextLabel":"Has completado los ocho módulos obligatorios - consulta tu registro completo de evaluaciones"}};
